# ============================================================================
# SHARED PARSING HELPERS
# ============================================================================

def normalise_swpc_product(data: Any) -> List[Dict]:
    '''
    Normalise a SWPC /products/ JSON payload to a list of dicts.

    Handles two layouts:
      1. Legacy: a list of lists, where the first inner list holds the
         column names and every later list holds the values.
      2. Current: a list of dicts, each already key-value.

    Returns an empty list for anything unrecognised.
    '''
    if not data or not isinstance(data, list):
        return []

    first = data[0]

    # Current format: already a list of dicts.
    if isinstance(first, dict):
        return [row for row in data if isinstance(row, dict)]

    # Legacy format: header row plus value rows.
    if isinstance(first, (list, tuple)):
        header = [str(h) for h in first]
        rows = []
        for values in data[1:]:
            if not isinstance(values, (list, tuple)):
                continue
            rows.append(dict(zip(header, values)))
        return rows

    return []


def as_float(value: Any, default: float = 0.0) -> float:
    '''Coerce a SWPC value to float, tolerating None, '' and strings.'''
    if value is None or value == '':
        return default
    try:
        return float(value)
    except (TypeError, ValueError):
        return default


def as_bool(value: Any, default: bool = False) -> bool:
    '''Coerce API booleans without treating the string "false" as true.'''
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return value != 0
    if isinstance(value, str):
        normalized = value.strip().lower()
        if normalized in {"true", "1", "yes", "y", "active"}:
            return True
        if normalized in {"false", "0", "no", "n", "", "inactive"}:
            return False
    return default


def parse_swpc_time(value: Any) -> Optional[datetime]:
    '''Parse any SWPC timestamp string to a timezone-aware UTC datetime.'''
    if not value:
        return None
    if isinstance(value, datetime):
        return value if value.tzinfo else value.replace(tzinfo=timezone.utc)

    text = str(value).strip().replace('Z', '')

    for fmt in ('%Y-%m-%dT%H:%M:%S.%f',
                '%Y-%m-%dT%H:%M:%S',
                '%Y-%m-%dT%H:%M',
                '%Y-%m-%d %H:%M:%S.%f',
                '%Y-%m-%d %H:%M:%S',
                '%Y-%m-%d %H:%M'):
        try:
            return datetime.strptime(text, fmt).replace(tzinfo=timezone.utc)
        except ValueError:
            continue

    try:
        parsed = datetime.fromisoformat(text)
        return parsed if parsed.tzinfo else parsed.replace(tzinfo=timezone.utc)
    except ValueError:
        return None


def get_key(row: Dict, *names: str, default: Any = None) -> Any:
    '''Fetch the first matching key from a dict, ignoring case.'''
    if not isinstance(row, dict):
        return default
    lowered = {str(k).lower(): v for k, v in row.items()}
    for name in names:
        if name in row:
            return row[name]
        if str(name).lower() in lowered:
            return lowered[str(name).lower()]
    return default


def newell_coupling(speed: float, by: float, bz: float) -> float:
    '''Newell coupling function dPhi_MP/dt in (km/s)^(4/3) nT^(2/3).'''
    try:
        b_t = math.hypot(by, bz)
        if speed <= 0:
            return float('nan')
        if b_t == 0:
            return 0.0
        theta_c = math.atan2(by, bz)
        return ((speed ** (4.0 / 3.0))
                * (b_t ** (2.0 / 3.0))
                * (abs(math.sin(theta_c / 2.0)) ** (8.0 / 3.0)))
    except (TypeError, ValueError, OverflowError):
        return float('nan')


def blank_if_zero(value: Any) -> float:
    '''Return NaN for a missing, zero or negative sample.'''
    v = as_float(value, default=float('nan'))
    if v is None:
        return float('nan')
    if v != v:  # NaN
        return float('nan')
    return v if v > 0 else float('nan')


# ============================================================================
# DATA CLASSES
# ============================================================================

@dataclass
class SolarFlare:
    """Represents a solar flare event"""
    start_time: datetime
    peak_time: Optional[datetime]
    end_time: Optional[datetime]
    class_type: str
    intensity: float
    location: Optional[str] = None
    active_region: Optional[str] = None
    source: str = "Unknown"

    @property
    def classification(self) -> str:
        return self.class_type

    @property
    def duration_minutes(self) -> Optional[int]:
        if self.end_time and self.start_time:
            return int((self.end_time - self.start_time).total_seconds() / 60)
        return None


@dataclass
class CME:
    """Represents a Coronal Mass Ejection"""
    start_time: datetime
    speed: float
    half_angle: Optional[float] = None
    latitude: Optional[float] = None
    longitude: Optional[float] = None
    cme_type: str = "Unknown"
    is_earth_directed: bool = False
    estimated_arrival: Optional[datetime] = None
    source: str = "Unknown"
    note: str = ""


@dataclass
class GeomagneticStorm:
    """Represents a geomagnetic storm event"""
    start_time: datetime
    kp_index: float
    g_scale: int
    end_time: Optional[datetime] = None
    source: str = "Unknown"


@dataclass
class SolarWindData:
    """Real-time solar wind measurements"""
    timestamp: datetime
    speed: float        # km/s
    density: float      # p/cm^3
    temperature: float  # K
    bz: float           # nT
    bt: float           # nT
    bx: Optional[float] = None
    by: Optional[float] = None
    source: str = "Unknown"
    active: bool = True

    @property
    def dynamic_pressure(self) -> float:
        '''Solar wind dynamic pressure P = 1.67e-6 n v^2, in nPa.'''
        return 1.67e-6 * self.density * (self.speed ** 2)

    @property
    def coupling(self) -> float:
        '''Newell coupling function for this sample.'''
        return newell_coupling(self.speed, self.by or 0.0, self.bz)


@dataclass
class XRayData:
    """X-ray flux measurements"""
    timestamp: datetime
    flux_short: float  # 0.05-0.4 nm
    flux_long: float   # 0.1-0.8 nm
    source: str = "GOES"


@dataclass
class ProtonData:
    """Energetic proton measurements"""
    timestamp: datetime
    flux_10mev: float
    flux_50mev: float
    flux_100mev: float
    source: str = "GOES"


@dataclass
class DataQuality:
    """Data quality metrics for each source"""
    source: str
    completeness: float  # 0-100%
    freshness: float     # 0-100%
    reliability: float   # 0-100%
    record_count: int
    data_gaps: int
    flags: List[str] = field(default_factory=list)

    @property
    def overall_score(self) -> float:
        return (self.completeness + self.freshness + self.reliability) / 3

    @property
    def status(self) -> str:
        if any(flag.startswith("UNAVAILABLE") for flag in self.flags):
            return "Unavailable"
        score = self.overall_score
        if score >= 90:
            return "Excellent"
        elif score >= 70:
            return "Good"
        elif score >= 50:
            return "Fair"
        else:
            return "Critical"


# ============================================================================
# API CLIENT CLASS
# ============================================================================

class SpaceWeatherAPI:
    """Handles all API requests to space weather data sources"""

    def __init__(self, nasa_api_key: str = NASA_API_KEY, timeout: int = 30):
        self.nasa_api_key = nasa_api_key
        self.timeout = timeout
        self.session = requests.Session()
        self.session.headers.update({
            'User-Agent': f'SolarMissionControl/{VERSION}',
            'Accept': 'application/json'
        })
        self._cache = {}
        self._cache_expiry = {}
        self.active_sw_source = "Unknown"
        self.last_request_error: Optional[str] = None
        self.donki_cooldown_until: Optional[datetime] = None
        self.recent_alert_messages: List[Dict] = []
        self.historical_alert_messages: List[Dict] = []

    def _get(self, url: str, params: Dict = None, cache_minutes: int = 5,
             retries: int = 3) -> Optional[Any]:
        """Cached JSON GET with bounded retries, content checks and secret-safe errors."""
        params = dict(params or {})
        is_donki = ('/DONKI-API/' in url or 'api.nasa.gov/DONKI' in url)
        # The CCMC DONKI API moved on 2026-09-30 and does not use the old
        # api.nasa.gov gateway key in its query string.
        if '/DONKI-API/' in url:
            params.pop('api_key', None)
        self.last_request_error = None
        if (is_donki and self.donki_cooldown_until and
                datetime.now(timezone.utc) < self.donki_cooldown_until):
            return None
        cache_key = f"{url}:{json.dumps(params, sort_keys=True)}"
        if cache_key in self._cache and datetime.now() < self._cache_expiry.get(cache_key, datetime.min):
            return self._cache[cache_key]
        safe_params = dict(params)
        if 'api_key' in safe_params:
            safe_params['api_key'] = '[REDACTED]'
        safe_target = requests.Request('GET', url, params=safe_params).prepare().url
        is_notebook = 'ipykernel' in sys.modules
        max_delay = 12.0 if is_notebook else 60.0
        for attempt in range(retries + 1):
            try:
                response = self.session.get(url, params=params, timeout=self.timeout)
                status = response.status_code
                if status == 429:
                    retry_after = response.headers.get('Retry-After', '').strip()
                    try:
                        requested = float(retry_after) if retry_after else 2.0 ** attempt
                    except ValueError:
                        requested = 2.0 ** attempt
                    delay = min(max_delay, max(1.0, requested))
                    self.last_request_error = 'HTTP 429 rate limited'
                    if is_donki:
                        self.donki_cooldown_until = datetime.now(timezone.utc) + timedelta(seconds=delay)
                    if is_notebook:
                        print(f"API rate limited (429); DONKI marked unavailable for this run.")
                        return None
                    if attempt < retries:
                        print(f"API rate limited (429); retrying in {delay:.0f}s...")
                        time.sleep(delay)
                        continue
                    print(f"API Error ({safe_target}): HTTPError, HTTP 429")
                    return None
                if 500 <= status < 600 and attempt < retries:
                    delay = min(max_delay, 2.0 ** attempt)
                    print(f"API temporarily unavailable ({status}); retrying in {delay:.0f}s...")
                    time.sleep(delay); continue
                response.raise_for_status()
                content_type = response.headers.get('Content-Type', '').lower()
                if 'json' not in content_type and not response.text.lstrip().startswith(('[', '{')):
                    self.last_request_error = f"Unexpected content type: {content_type or 'unknown'}"
                    if is_donki:
                        # One HTML maintenance/error page means the provider is
                        # unavailable for this run. Suppress three near-identical
                        # FLR/CME/GST errors and continue with SWPC/GOES/RTSW.
                        self.donki_cooldown_until = datetime.now(timezone.utc) + timedelta(minutes=15)
                        print('  DONKI API returned a non-JSON response; DONKI marked unavailable for this run.')
                    else:
                        print(f"API Error ({safe_target}): {self.last_request_error}")
                    return None
                try:
                    data = response.json()
                except ValueError:
                    self.last_request_error = 'Invalid JSON response'
                    print(f"API Error ({safe_target}): Invalid JSON response")
                    return None
                self._cache[cache_key] = data
                self._cache_expiry[cache_key] = datetime.now() + timedelta(minutes=cache_minutes)
                return data
            except requests.exceptions.RequestException as exc:
                status = getattr(getattr(exc, 'response', None), 'status_code', None)
                self.last_request_error = f"{type(exc).__name__}" + (f" HTTP {status}" if status else '')
                if is_donki and status in (401, 403, 404):
                    self.donki_cooldown_until = datetime.now(timezone.utc) + timedelta(minutes=15)
                transient = status is None or status >= 500
                if transient and attempt < retries:
                    delay = min(max_delay, 2.0 ** attempt)
                    print(f"API request failed; retrying in {delay:.0f}s: {type(exc).__name__}")
                    time.sleep(delay); continue
                print(f"API Error ({safe_target}): {self.last_request_error}")
                return None
        return None

    def fetch_image(self, url: str, timeout: Optional[int] = None) -> Optional[Tuple[bytes, str]]:
        """Download an image safely and return its bytes and MIME type.

        Image retrieval is deliberately separate from the JSON request path.
        Invalid responses return None so optional imagery cannot stop a report.
        """
        try:
            response = self.session.get(url, timeout=timeout or self.timeout)
            response.raise_for_status()
            content = response.content
            content_type = response.headers.get('Content-Type', '').split(';', 1)[0].lower()
            if not content:
                print(f"  Image download returned an empty response: {url}")
                return None
            if not content_type.startswith('image/'):
                print(f"  Image download returned {content_type or 'unknown content'}: {url}")
                return None
            return content, content_type
        except requests.exceptions.RequestException as exc:
            status = getattr(getattr(exc, 'response', None), 'status_code', None)
            suffix = f" HTTP {status}" if status is not None else ''
            print(f"  Image download failed ({type(exc).__name__}{suffix}): {url}")
            return None

    def get_xray_data(self, days: int = 1) -> List[XRayData]:
        """Fetch GOES X-ray flux data"""
        endpoint = ENDPOINTS['swpc_xray_3day'] if days > 1 else ENDPOINTS['swpc_xray_1min']
        data = self._get(endpoint)

        if not data:
            return []

        # The GOES x-ray file emits TWO records per timestamp, one per
        # energy channel (0.05-0.4 nm and 0.1-0.8 nm). Records are
        # grouped by timestamp and each channel written to its own field.
        by_time: Dict[str, Dict[str, float]] = defaultdict(dict)

        for item in data:
            if not isinstance(item, dict):
                continue
            time_tag = item.get('time_tag')
            if not time_tag:
                continue
            flux = as_float(item.get('flux'))
            energy = str(item.get('energy', ''))

            if '0.05' in energy:
                by_time[time_tag]['short'] = flux
            elif '0.1' in energy or '0.8' in energy:
                by_time[time_tag]['long'] = flux
            else:
                by_time[time_tag].setdefault('long', flux)

        results = []
        for time_tag, fluxes in by_time.items():
            timestamp = parse_swpc_time(time_tag)
            if timestamp is None:
                continue
            results.append(XRayData(
                timestamp=timestamp,
                flux_short=fluxes.get('short', 0.0),
                flux_long=fluxes.get('long', 0.0),
                source="GOES"
            ))

        return sorted(results, key=lambda x: x.timestamp)

    def get_proton_data(self, days: int = 1) -> List[ProtonData]:
        """Fetch GOES proton flux data"""
        endpoint = ENDPOINTS['swpc_protons_3day'] if days > 1 else ENDPOINTS['swpc_protons']
        data = self._get(endpoint)

        if not data:
            return []

        by_time = defaultdict(dict)
        for item in data:
            if not isinstance(item, dict):
                continue
            try:
                timestamp = item['time_tag']
                energy = str(item.get('energy', ''))
                flux = as_float(item.get('flux'))

                # Order matters: the 100 MeV label is '>=100 MeV' and
                # would otherwise be captured by the '10' branch.
                if '100' in energy:
                    by_time[timestamp]['flux_100mev'] = flux
                elif '50' in energy:
                    by_time[timestamp]['flux_50mev'] = flux
                elif '10' in energy:
                    by_time[timestamp]['flux_10mev'] = flux
            except (KeyError, TypeError):
                continue

        results = []
        for timestamp_str, fluxes in by_time.items():
            timestamp = parse_swpc_time(timestamp_str)
            if timestamp is None:
                continue
            results.append(ProtonData(
                timestamp=timestamp,
                flux_10mev=fluxes.get('flux_10mev', 0.0),
                flux_50mev=fluxes.get('flux_50mev', 0.0),
                flux_100mev=fluxes.get('flux_100mev', 0.0),
                source="GOES"
            ))

        return sorted(results, key=lambda x: x.timestamp)

    def get_kp_index(self) -> List[Dict]:
        """Fetch current and recent Kp index values"""
        data = self._get(ENDPOINTS['swpc_kp'])

        rows = normalise_swpc_product(data)
        if not rows:
            return []

        results = []
        for row in rows:
            time_tag = get_key(row, 'time_tag')
            if not time_tag:
                continue
            results.append({
                'time_tag': time_tag,
                'kp': as_float(get_key(row, 'Kp', 'kp', 'kp_index')),
                'kp_fraction': as_float(get_key(row, 'Kp_fraction', 'kp_fraction')),
                'observed': get_key(row, 'observed', default='observed')
            })

        return results

    def get_kp_forecast(self) -> List[Dict]:
        """Fetch current Kp forecasts and discard stale rows."""
        data = self._get(ENDPOINTS['swpc_kp_forecast'])
        rows = normalise_swpc_product(data)
        if not rows:
            return []

        now = datetime.now(timezone.utc)
        earliest = now - timedelta(hours=3)
        latest = now + timedelta(days=4)
        results = []
        for row in rows:
            time_tag = get_key(row, 'time_tag')
            stamp = parse_swpc_time(time_tag)
            if stamp is None or stamp < earliest or stamp > latest:
                continue
            results.append({
                'time_tag': time_tag,
                'kp': as_float(get_key(row, 'kp', 'Kp', 'kp_index')),
                'observed': get_key(row, 'observed', default='predicted'),
                '_timestamp': stamp,
            })

        results.sort(key=lambda item: item['_timestamp'])
        for item in results:
            item.pop('_timestamp', None)
        return results

    def get_alerts(self) -> List[Dict]:
        """Return currently effective SWPC messages and retain recent/history groups."""
        data = self._get(ENDPOINTS['swpc_alerts'])
        rows = [item for item in (data or []) if isinstance(item, dict)]
        now = datetime.now(timezone.utc); recent_cutoff = now - timedelta(hours=72)
        active, recent, historical = [], [], []
        for item in rows:
            text = str(get_key(item, 'message', 'product_text', default=''))
            issued = parse_swpc_time(get_key(item, 'issue_datetime', 'issue_time', 'time_tag'))
            upper = text.upper()
            cancelled = any(token in upper for token in ('CANCEL WATCH', 'CANCEL WARNING', 'CANCEL ALERT'))
            summary = 'SUMMARY:' in upper or 'SPACE WEATHER MESSAGE CODE: SUMP' in upper
            explicit_end = parse_swpc_time(get_key(item, 'valid_to', 'expiration_time', 'end_time'))
            effective = (not cancelled and not summary and
                         ((explicit_end and explicit_end >= now) or (issued and issued >= recent_cutoff)))
            if effective:
                active.append(item)
            elif issued and issued >= recent_cutoff:
                recent.append(item)
            else:
                historical.append(item)
        self.recent_alert_messages = recent
        self.historical_alert_messages = historical
        return active

    def get_dst_index(self) -> List[Dict]:
        """Fetch Dst index data"""
        data = self._get(ENDPOINTS['swpc_dst'])

        rows = normalise_swpc_product(data)
        if not rows:
            return []

        results = []
        for row in rows:
            time_tag = get_key(row, 'time_tag')
            if not time_tag:
                continue
            results.append({
                'time_tag': time_tag,
                'dst': as_float(get_key(row, 'dst', 'Dst'))
            })

        return results

    def get_flare_probabilities(self) -> Dict:
        """Fetch solar flare probabilities"""
        data = self._get(ENDPOINTS['swpc_flare_prob'])

        if not data:
            return {}

        if isinstance(data, list) and len(data) > 0:
            return data[0] if isinstance(data[0], dict) else {}
        return data if isinstance(data, dict) else {}

    def get_f107_series(self) -> List[Dict]:
        """Return the monthly F10.7 series with a centered 13-month smooth."""
        rows = [r for r in (self._get(ENDPOINTS['swpc_f107'], cache_minutes=360) or []) if isinstance(r, dict)]
        parsed = []
        for row in rows:
            tag = str(get_key(row, 'time-tag', 'time_tag', 'date', default=''))
            value = as_float(get_key(row, 'f10.7', 'f107', 'flux'), float('nan'))
            if tag and math.isfinite(value):
                stamp = parse_swpc_time(tag + '-01') if re.fullmatch(r'\d{4}-\d{2}', tag) else parse_swpc_time(tag)
                if stamp:
                    parsed.append({'time_tag': tag, 'timestamp': stamp, 'flux': value, 'smoothed_13m': None})
        parsed.sort(key=lambda row: row['timestamp'])
        for index in range(6, len(parsed)-6):
            parsed[index]['smoothed_13m'] = sum(r['flux'] for r in parsed[index-6:index+7]) / 13.0
        return parsed

    def get_f107_flux(self) -> Dict:
        series = self.get_f107_series()
        return dict(series[-1]) if series else {}

    @staticmethod
    def _magnetic_complexity_flag(mag_class: str) -> str:
        """Normalize NOAA magnetic classes to an operational complexity flag."""
        value = (mag_class or '').upper().replace(' ', '')
        if 'D' in value or 'DELTA' in value:
            return 'HIGH (delta-bearing)'
        if 'G' in value or 'GAMMA' in value:
            return 'ELEVATED (gamma)'
        if 'B' in value or 'BETA' in value:
            return 'MODERATE (beta)'
        if 'A' in value or 'ALPHA' in value:
            return 'LOW (alpha)'
        return 'UNKNOWN'

    def get_solar_regions(self) -> List[Dict]:
        """Return de-duplicated regions from the latest NOAA observation date."""
        rows = [r for r in (self._get(ENDPOINTS['swpc_regions'], cache_minutes=30) or []) if isinstance(r, dict)]
        latest = max((str(get_key(r, 'observed_date', default='')) for r in rows), default='')
        by_number = {}
        for row in rows:
            if latest and str(get_key(row, 'observed_date', default='')) != latest:
                continue
            number = int(as_float(get_key(row, 'region'), -1))
            if number < 0:
                continue
            by_number[number] = {
                'observed_date': str(get_key(row, 'observed_date', default='')),
                'region': number, 'location': str(get_key(row, 'location', default='N/A') or 'N/A'),
                'area': as_float(get_key(row, 'area')), 'spots': int(as_float(get_key(row, 'number_spots'))),
                'spot_class': str(get_key(row, 'spot_class', default='N/A') or 'N/A'),
                'mag_class': str(get_key(row, 'mag_class', default='N/A') or 'N/A'),
                'complexity': self._magnetic_complexity_flag(
                    str(get_key(row, 'mag_class', default='N/A') or 'N/A')),
                'c_probability': as_float(get_key(row, 'c_flare_probability')),
                'm_probability': as_float(get_key(row, 'm_flare_probability')),
                'x_probability': as_float(get_key(row, 'x_flare_probability')),
                'proton_probability': as_float(get_key(row, 'proton_probability')),
            }
        return sorted(by_number.values(), key=lambda r: (-r['m_probability'], -r['x_probability'], -r['area'], r['region']))

    # ------------------------------------------------------------------
    # Real-Time Solar Wind (RTSW) - L1 fleet
    # ------------------------------------------------------------------

    def get_rtsw_solar_wind(self, active_only: bool = True) -> List[SolarWindData]:
        '''
        Fetch real-time solar wind from the RTSW L1 fleet.

        Parameters
        ----------
        active_only : bool
            If True, keep only records SWPC flagged as operational.
            Set False to see every spacecraft for comparison.

        Returns
        -------
        List of SolarWindData sorted by time.
        '''
        mag_data = self._get(ENDPOINTS['rtsw_mag'])
        wind_data = self._get(ENDPOINTS['rtsw_wind'])

        if not mag_data and not wind_data:
            return []

        # Index the magnetometer records by (time_tag, source).
        mag_by_key: Dict[Tuple[str, str], Dict] = {}
        if isinstance(mag_data, list):
            for item in mag_data:
                if not isinstance(item, dict):
                    continue
                key = (str(item.get('time_tag')), str(item.get('source')))
                mag_by_key[key] = {
                    'bx': as_float(item.get('bx_gsm')),
                    'by': as_float(item.get('by_gsm')),
                    'bz': as_float(item.get('bz_gsm')),
                    'bt': as_float(item.get('bt')),
                }

        results = []
        if isinstance(wind_data, list):
            for item in wind_data:
                if not isinstance(item, dict):
                    continue

                is_active = as_bool(item.get('active'), default=False)
                if active_only and not is_active:
                    continue

                timestamp = parse_swpc_time(item.get('time_tag'))
                if timestamp is None:
                    continue

                source = str(item.get('source', 'RTSW'))
                mag = mag_by_key.get((str(item.get('time_tag')), source), {})
                # Preserve an unmatched magnetic sample as missing data.
                # Using zero would falsely imply a measured quiet IMF.
                missing = float('nan')

                results.append(SolarWindData(
                    timestamp=timestamp,
                    speed=as_float(item.get('proton_speed')),
                    density=as_float(item.get('proton_density')),
                    temperature=as_float(item.get('proton_temperature')),
                    bz=mag.get('bz', missing),
                    bt=mag.get('bt', missing),
                    bx=mag.get('bx', missing),
                    by=mag.get('by', missing),
                    source=source,
                    active=is_active
                ))

        results.sort(key=lambda x: x.timestamp)

        if results:
            self.active_sw_source = results[-1].source

        return results

    # ------------------------------------------------------------------
    # NASA DONKI Data
    # ------------------------------------------------------------------

    def get_donki_flares(self, start_date: datetime, end_date: datetime) -> List[SolarFlare]:
        """Fetch solar flare data from NASA DONKI"""
        params = {
            'startDate': start_date.strftime('%Y-%m-%d'),
            'endDate': end_date.strftime('%Y-%m-%d'),
            'api_key': self.nasa_api_key
        }

        data = self._get(ENDPOINTS['donki_flr'], params, cache_minutes=15)

        if not data or not isinstance(data, list):
            return []

        results = []
        for item in data:
            if not isinstance(item, dict):
                continue
            try:
                start_time = parse_swpc_time(item.get('beginTime'))
                if start_time is None:
                    continue

                peak_time = parse_swpc_time(item.get('peakTime'))
                end_time = parse_swpc_time(item.get('endTime'))

                class_type = item.get('classType') or 'Unknown'
                intensity = self._parse_flare_intensity(class_type)

                results.append(SolarFlare(
                    start_time=start_time,
                    peak_time=peak_time,
                    end_time=end_time,
                    class_type=class_type,
                    intensity=intensity,
                    location=item.get('sourceLocation'),
                    active_region=item.get('activeRegionNum'),
                    source="DONKI"
                ))
            except (ValueError, KeyError, TypeError):
                continue

        return sorted(results, key=lambda x: x.start_time, reverse=True)

    def get_donki_cmes(self, start_date: datetime, end_date: datetime) -> List[CME]:
        """Fetch CME data from NASA DONKI"""
        params = {
            'startDate': start_date.strftime('%Y-%m-%d'),
            'endDate': end_date.strftime('%Y-%m-%d'),
            'api_key': self.nasa_api_key
        }

        data = self._get(ENDPOINTS['donki_cme'], params, cache_minutes=15)

        if not data or not isinstance(data, list):
            return []

        results = []
        for item in data:
            if not isinstance(item, dict):
                continue
            try:
                start_time = parse_swpc_time(item.get('startTime'))
                if start_time is None:
                    continue

                analyses = item.get('cmeAnalyses') or []
                speed = 0.0
                half_angle = None
                latitude = None
                longitude = None
                is_earth_directed = False
                estimated_arrival = None
                note = item.get('note') or ''
                cme_type = note[:50] if note else 'Unknown'

                if analyses:
                    analysis = next(
                        (an for an in analyses
                         if isinstance(an, dict) and an.get('isMostAccurate')),
                        analyses[-1]
                    )

                    speed = as_float(analysis.get('speed'))
                    half_angle = (as_float(analysis.get('halfAngle'))
                                  if analysis.get('halfAngle') is not None else None)
                    latitude = (as_float(analysis.get('latitude'))
                                if analysis.get('latitude') is not None else None)
                    longitude = (as_float(analysis.get('longitude'))
                                 if analysis.get('longitude') is not None else None)
                    cme_type = analysis.get('type', cme_type)

                    # Earth-directed flag is set ONLY by a WSA-Enlil
                    # predicted arrival at Earth or by the source
                    # longitude test below.
                    enlil = analysis.get('enlilList') or []
                    for e in enlil:
                        if not isinstance(e, dict):
                            continue
                        arrival = parse_swpc_time(e.get('estimatedShockArrivalTime'))
                        if arrival:
                            estimated_arrival = arrival
                            is_earth_directed = True
                            break
                        if e.get('isEarthGB'):
                            is_earth_directed = True

                if longitude is not None and -45 <= longitude <= 45:
                    is_earth_directed = True

                results.append(CME(
                    start_time=start_time,
                    speed=speed,
                    half_angle=half_angle,
                    latitude=latitude,
                    longitude=longitude,
                    cme_type=cme_type,
                    is_earth_directed=is_earth_directed,
                    estimated_arrival=estimated_arrival,
                    source="DONKI",
                    note=note[:100]
                ))
            except (ValueError, KeyError, TypeError):
                continue

        return sorted(results, key=lambda x: x.start_time, reverse=True)

    def get_donki_geomagnetic_storms(self, start_date: datetime,
                                     end_date: datetime) -> List[GeomagneticStorm]:
        """Fetch geomagnetic storm data from NASA DONKI"""
        params = {
            'startDate': start_date.strftime('%Y-%m-%d'),
            'endDate': end_date.strftime('%Y-%m-%d'),
            'api_key': self.nasa_api_key
        }

        data = self._get(ENDPOINTS['donki_gst'], params, cache_minutes=15)

        if not data or not isinstance(data, list):
            return []

        results = []
        for item in data:
            if not isinstance(item, dict):
                continue
            try:
                start_time = parse_swpc_time(item.get('startTime'))
                if start_time is None:
                    continue

                kp_indices = item.get('allKpIndex') or []
                max_kp = 0.0
                for kp in kp_indices:
                    if not isinstance(kp, dict):
                        continue
                    kp_val = as_float(kp.get('kpIndex'))
                    max_kp = max(max_kp, kp_val)

                results.append(GeomagneticStorm(
                    start_time=start_time,
                    kp_index=max_kp,
                    g_scale=self._kp_to_g_scale(max_kp),
                    source="DONKI"
                ))
            except (ValueError, KeyError, TypeError):
                continue

        return sorted(results, key=lambda x: x.start_time, reverse=True)

    @staticmethod
    def _parse_flare_intensity(class_type: str) -> float:
        """Parse flare class to intensity value in W/m^2."""
        if not class_type:
            return 0.0

        class_type = str(class_type).upper().strip()
        scales = {'X': 1e-4, 'M': 1e-5, 'C': 1e-6, 'B': 1e-7, 'A': 1e-8}

        letter = class_type[:1]
        if letter not in scales:
            return 0.0

        magnitude = class_type[1:].strip()
        try:
            multiplier = float(magnitude) if magnitude else 1.0
        except ValueError:
            multiplier = 1.0

        return multiplier * scales[letter]

    def _kp_to_g_scale(self, kp: float) -> int:
        """Convert Kp index to G-scale"""
        if kp >= 9:
            return 5
        elif kp >= 8:
            return 4
        elif kp >= 7:
            return 3
        elif kp >= 6:
            return 2
        elif kp >= 5:
            return 1
        return 0


# ============================================================================
# SUNPY AND ASTROPY INTEGRATION
# ============================================================================

class SunPyAstropyIntegration:
    """Integration with SunPy and Astropy for additional solar data"""

    def __init__(self):
        self.has_sunpy = HAS_SUNPY
        self.has_astropy = HAS_ASTROPY

    def get_goes_flares_sunpy(self, start_date: datetime,
                              end_date: datetime) -> List[SolarFlare]:
        """Fetch GOES flare data from the HEK via SunPy"""
        if not self.has_sunpy:
            return []

        try:
            time_range = TimeRange(start_date, end_date)
            result = Fido.search(
                a.Time(time_range),
                a.hek.EventType('FL'),
                a.hek.OBS.Observatory == 'GOES'
            )

            flares = []
            if len(result) > 0 and len(result[0]) > 0:
                for record in result[0]:
                    try:
                        start = parse_swpc_time(record.get('event_starttime'))
                        if start is None:
                            continue
                        peak = parse_swpc_time(record.get('event_peaktime'))
                        end = parse_swpc_time(record.get('event_endtime'))

                        class_type = record.get('fl_goescls') or 'Unknown'

                        intensity = SpaceWeatherAPI._parse_flare_intensity(
                            class_type)

                        flares.append(SolarFlare(
                            start_time=start,
                            peak_time=peak,
                            end_time=end,
                            class_type=class_type,
                            intensity=intensity,
                            location=record.get('hgs_coord', None),
                            active_region=record.get('ar_noaanum', None),
                            source="SunPy/HEK"
                        ))
                    except Exception:
                        continue

            return flares
        except Exception as e:
            print(f"SunPy flare search error: {e}")
            return []

    def get_current_time_astropy(self) -> datetime:
        """Get current UTC time using Astropy"""
        if not self.has_astropy:
            return datetime.now(timezone.utc)

        try:
            return Time.now().datetime.replace(tzinfo=timezone.utc)
        except Exception:
            return datetime.now(timezone.utc)

    def convert_coordinates(self, lat: float, lon: float) -> Optional[str]:
        """Convert heliographic coordinates to a NsEw string"""
        try:
            ns = "N" if lat >= 0 else "S"
            ew = "E" if lon >= 0 else "W"
            return f"{ns}{abs(lat):.0f}{ew}{abs(lon):.0f}"
        except (TypeError, ValueError):
            return None


# ============================================================================
# RISK ASSESSMENT ENGINE
# ============================================================================

class RiskAssessmentEngine:
    """Calculates risk levels from space weather data"""

    def __init__(self):
        self.weights = {
            'xray': 0.30,
            'proton': 0.25,
            'geomagnetic': 0.25,
            'solar_wind': 0.20
        }

    def calculate_xray_risk(self, flux: float, classification: str) -> Tuple[int, str]:
        """Calculate X-ray risk (0-100)"""
        if not classification or classification == "N/A":
            return 0, "No data"

        classification = str(classification).upper()

        if classification.startswith('X'):
            try:
                val = float(classification[1:])
                if val >= 10:
                    return 100, "Extreme X-ray event"
                elif val >= 5:
                    return 90, "Major X-ray event"
                elif val >= 1:
                    return 70, "Significant X-ray event"
            except ValueError:
                pass
            return 60, "X-class flare"
        elif classification.startswith('M'):
            try:
                val = float(classification[1:])
                if val >= 5:
                    return 50, "Strong M-class flare"
            except ValueError:
                pass
            return 40, "M-class flare"
        elif classification.startswith('C'):
            return 20, "Minor C-class activity"

        return 5, "Background levels"

    def calculate_proton_risk(self, flux_10mev: float) -> Tuple[int, str]:
        """Calculate proton radiation risk (0-100)"""
        if flux_10mev >= 100000:
            return 100, "Extreme proton storm (S5)"
        elif flux_10mev >= 10000:
            return 85, "Severe proton storm (S4)"
        elif flux_10mev >= 1000:
            return 65, "Strong proton storm (S3)"
        elif flux_10mev >= 100:
            return 45, "Moderate proton storm (S2)"
        elif flux_10mev >= 10:
            return 25, "Minor proton storm (S1)"
        return 5, "No significant proton activity"

    def calculate_geomagnetic_risk(self, kp: float) -> Tuple[int, str]:
        """Calculate geomagnetic activity risk (0-100)"""
        if kp >= 9:
            return 100, "Extreme geomagnetic storm (G5)"
        elif kp >= 8:
            return 85, "Severe geomagnetic storm (G4)"
        elif kp >= 7:
            return 65, "Strong geomagnetic storm (G3)"
        elif kp >= 6:
            return 45, "Moderate geomagnetic storm (G2)"
        elif kp >= 5:
            return 25, "Minor geomagnetic storm (G1)"
        return 5, "Quiet geomagnetic conditions"

    def calculate_solar_wind_risk(self, speed: float, bz: float,
                                  density: float) -> Tuple[int, str]:
        """Calculate solar wind impact risk (0-100)"""
        risk = 0
        reasons = []

        if speed >= 800:
            risk += 40
            reasons.append("Very high speed stream")
        elif speed >= 600:
            risk += 25
            reasons.append("High speed stream")
        elif speed >= 500:
            risk += 15
            reasons.append("Elevated solar wind speed")
        elif speed >= 400:
            risk += 5
            reasons.append("Moderate solar wind")

        if bz <= -20:
            risk += 40
            reasons.append("Strongly southward IMF")
        elif bz <= -10:
            risk += 25
            reasons.append("Southward IMF")
        elif bz <= -5:
            risk += 10
            reasons.append("Weakly southward IMF")

        if density >= 20:
            risk += 20
            reasons.append("High solar wind density")
        elif density >= 10:
            risk += 10
            reasons.append("Elevated solar wind density")

        reason = ", ".join(reasons) if reasons else "Normal solar wind conditions"
        return min(100, risk), reason

    def calculate_overall_risk(self, xray_flux: float, xray_class: str,
                               proton_flux: float, kp: float,
                               solar_wind_speed: float, bz: float,
                               density: float) -> Dict:
        """Calculate overall space weather risk assessment"""

        xray_risk, xray_reason = self.calculate_xray_risk(xray_flux, xray_class)
        proton_risk, proton_reason = self.calculate_proton_risk(proton_flux)
        geo_risk, geo_reason = self.calculate_geomagnetic_risk(kp)
        sw_risk, sw_reason = self.calculate_solar_wind_risk(solar_wind_speed, bz, density)

        overall = (
            xray_risk * self.weights['xray'] +
            proton_risk * self.weights['proton'] +
            geo_risk * self.weights['geomagnetic'] +
            sw_risk * self.weights['solar_wind']
        )

        risks = {
            'X-Ray': xray_risk,
            'Proton': proton_risk,
            'Geomagnetic': geo_risk,
            'Solar Wind': sw_risk
        }
        dominant = max(risks, key=risks.get)

        if overall >= 80:
            level = "EXTREME"
        elif overall >= 60:
            level = "SEVERE"
        elif overall >= 40:
            level = "MODERATE"
        elif overall >= 20:
            level = "MINOR"
        else:
            level = "NOMINAL"

        concerns = []
        if xray_risk >= 40:
            concerns.append("Elevated solar X-ray activity")
        if proton_risk >= 40:
            concerns.append("Elevated radiation environment")
        if geo_risk >= 40:
            concerns.append("Geomagnetic disturbance")
        if sw_risk >= 40:
            concerns.append("Enhanced solar wind conditions")

        return {
            'overall_risk': int(overall),
            'level': level,
            'xray_risk': xray_risk,
            'proton_risk': proton_risk,
            'geomagnetic_risk': geo_risk,
            'solar_wind_risk': sw_risk,
            'dominant_factor': dominant,
            'concerns': concerns if concerns else ["No significant concerns"],
            'xray_reason': xray_reason,
            'proton_reason': proton_reason,
            'geo_reason': geo_reason,
            'sw_reason': sw_reason
        }


# ============================================================================
# DATA AGGREGATOR
# ============================================================================

class SpaceWeatherAggregator:
    """Aggregates data from all sources"""

    def __init__(self, nasa_api_key: str = NASA_API_KEY):
        self.api = SpaceWeatherAPI(nasa_api_key)
        self.sunpy_astropy = SunPyAstropyIntegration()
        self.risk_engine = RiskAssessmentEngine()

        self.xray_data: List[XRayData] = []
        self.proton_data: List[ProtonData] = []
        self.solar_wind_data: List[SolarWindData] = []
        self.flares: List[SolarFlare] = []
        self.cmes: List[CME] = []
        self.geomagnetic_storms: List[GeomagneticStorm] = []
        self.kp_data: List[Dict] = []
        self.kp_forecast: List[Dict] = []
        self.alerts: List[Dict] = []
        self.recent_alert_messages: List[Dict] = []
        self.historical_alert_messages: List[Dict] = []
        self.donki_available: bool = True
        self.donki_errors: List[str] = []
        self.flare_probabilities: Dict = {}
        self.dst_data: List[Dict] = []
        self.f107_flux: Dict = {}
        self.f107_series: List[Dict] = []
        self.solar_regions: List[Dict] = []

        self.data_quality: Dict[str, DataQuality] = {}
        self.last_update: Optional[datetime] = None

    def fetch_all_data(self, hours_back: int = 48, hours_forward: int = 48):
        """Fetch all space weather data"""
        if not HAS_NUMPY:
            print("  Warning: NumPy is unavailable; advanced analysis will be limited.")
        print("Fetching space weather data from all sources...")

        now = datetime.now(timezone.utc)
        start_date = now - timedelta(hours=hours_back)
        end_date = now

        print("  Fetching GOES satellite data...")
        cutoff = now - timedelta(hours=max(1, hours_back))
        self.xray_data = [
            row for row in self.api.get_xray_data(days=3)
            if row.timestamp >= cutoff
        ]
        self.proton_data = [
            row for row in self.api.get_proton_data(days=3)
            if row.timestamp >= cutoff
        ]

        # here is the modification of the GOES quality window: the
        # completeness denominator is the full 72 h horizon of the feed
        # that was fetched, not the hours_back used to clip it.
        self.data_quality['GOES'] = self._assess_data_quality(
            "GOES Satellite", self.xray_data,
            expected_interval_minutes=1, max_age_minutes=10,
            assessment_hours=max(1, hours_back)
        )

        print("  Fetching RTSW solar wind data (L1 fleet)...")
        self.solar_wind_data = [
            row for row in self.api.get_rtsw_solar_wind(active_only=True)
            if row.timestamp >= cutoff
        ]

        if self.solar_wind_data:
            print(f"  Active solar wind source: {self.api.active_sw_source}")
        else:
            print("  No active-flagged records; retrying without the filter...")
            self.solar_wind_data = [
                row for row in self.api.get_rtsw_solar_wind(active_only=False)
                if row.timestamp >= cutoff
            ]

        self.data_quality['RTSW'] = self._assess_data_quality(
            f"RTSW L1 ({self.api.active_sw_source})", self.solar_wind_data,
            expected_interval_minutes=1, max_age_minutes=15,
            assessment_hours=max(1, hours_back)
        )
        if self.solar_wind_data:
            latest_sw = max(row.timestamp for row in self.solar_wind_data)
            sw_age = max(0.0, (now - latest_sw).total_seconds() / 60.0)
            self.data_quality['RTSW'].flags.append(
                f"Latest sample: {latest_sw.isoformat()} UTC; age {sw_age:.1f} minutes")

        print("  Fetching NOAA SWPC data...")
        self.kp_data = self.api.get_kp_index()
        self.kp_forecast = self.api.get_kp_forecast()
        self.alerts = self.api.get_alerts()
        self.recent_alert_messages = list(self.api.recent_alert_messages)
        self.historical_alert_messages = list(self.api.historical_alert_messages)
        self.flare_probabilities = self.api.get_flare_probabilities()
        self.dst_data = self.api.get_dst_index()
        self.f107_series = self.api.get_f107_series()
        self.f107_flux = dict(self.f107_series[-1]) if self.f107_series else {}
        self.solar_regions = self.api.get_solar_regions()

        self.data_quality['SWPC'] = self._assess_swpc_quality()

        print("  Fetching NASA DONKI data...")
        self.donki_available = True; self.donki_errors = []
        self.flares = self.api.get_donki_flares(start_date, end_date)
        if self.api.last_request_error: self.donki_errors.append('FLR: ' + self.api.last_request_error)
        if self.api.donki_cooldown_until and datetime.now(timezone.utc) < self.api.donki_cooldown_until:
            self.cmes, self.geomagnetic_storms = [], []
            self.donki_errors.append('Remaining DONKI calls skipped during rate-limit cooldown')
        else:
            self.cmes = self.api.get_donki_cmes(start_date, end_date)
            if self.api.last_request_error: self.donki_errors.append('CME: ' + self.api.last_request_error)
            self.geomagnetic_storms = self.api.get_donki_geomagnetic_storms(start_date, end_date)
            if self.api.last_request_error: self.donki_errors.append('GST: ' + self.api.last_request_error)
        self.donki_available = not self.donki_errors
        self.data_quality['DONKI'] = self._assess_donki_quality()

        if self.sunpy_astropy.has_sunpy:
            print("  Fetching additional data via SunPy...")
            sunpy_flares = self.sunpy_astropy.get_goes_flares_sunpy(start_date, now)
            for flare in sunpy_flares:
                duplicate = any(
                    abs((flare.start_time - existing.start_time).total_seconds()) <= 300
                    and (not flare.active_region or not existing.active_region
                         or str(flare.active_region) == str(existing.active_region))
                    for existing in self.flares
                )
                if not duplicate:
                    self.flares.append(flare)

        self.last_update = now
        print("Data fetch complete.")

    def _assess_data_quality(self, source: str, data: List,
                             expected_interval_minutes: int = 1,
                             max_age_minutes: int = 10,
                             assessment_hours: float = 24.0) -> DataQuality:
        """Assess data quality for a given dataset"""
        flags = []

        if not data:
            return DataQuality(
                source=source, completeness=0, freshness=0, reliability=0,
                record_count=0, data_gaps=0, flags=["No data available"]
            )

        record_count = len(data)
        now = datetime.now(timezone.utc)

        try:
            latest = max(d.timestamp for d in data if hasattr(d, 'timestamp'))
            age_minutes = (now - latest).total_seconds() / 60
            freshness = max(0.0, 100 - (age_minutes / max_age_minutes) * 100)
            if freshness < 50:
                flags.append("Data may be stale")
        except (ValueError, AttributeError, TypeError):
            freshness = 0.0
            flags.append("Cannot determine data freshness")

        data_gaps = 0
        if len(data) > 1:
            sorted_data = sorted(
                (d for d in data if hasattr(d, 'timestamp')),
                key=lambda x: x.timestamp
            )
            for i in range(1, len(sorted_data)):
                gap = (sorted_data[i].timestamp
                       - sorted_data[i - 1].timestamp).total_seconds() / 60
                if gap > expected_interval_minutes * 3:
                    data_gaps += 1

        if data_gaps > 0:
            flags.append(f"{data_gaps} data gaps detected")

        expected_records = max(1.0, assessment_hours * 60 / expected_interval_minutes)
        completeness = min(100.0, (record_count / expected_records) * 100)
        if completeness < 50:
            flags.append("Low data completeness")

        reliability = (freshness * 0.4 + completeness * 0.4
                       + (100 - min(100, data_gaps * 10)) * 0.2)

        return DataQuality(
            source=source, completeness=completeness, freshness=freshness,
            reliability=reliability, record_count=record_count,
            data_gaps=data_gaps, flags=flags
        )

    def _assess_swpc_quality(self) -> DataQuality:
        """Assess SWPC data quality"""
        flags = []
        total_records = len(self.kp_data) + len(self.alerts)

        if not self.kp_data:
            flags.append("No Kp data")
        if not self.alerts:
            flags.append("No alerts data")

        completeness = min(100.0, total_records / 50 * 100)

        freshness = 0.0
        if self.kp_data:
            latest_dt = parse_swpc_time(self.kp_data[-1].get('time_tag'))
            if latest_dt:
                age = (datetime.now(timezone.utc) - latest_dt).total_seconds() / 3600
                freshness = max(0.0, 100 - age * 10)
            else:
                flags.append("Cannot parse Kp timestamps")

        reliability = (completeness * 0.5 + freshness * 0.5)
        data_gaps = len([f for f in flags if 'No' in f])

        return DataQuality(
            source="NOAA Space Weather Prediction Center",
            completeness=completeness, freshness=freshness,
            reliability=reliability, record_count=total_records,
            data_gaps=data_gaps, flags=flags if flags else ["None"]
        )

    def _assess_donki_quality(self) -> DataQuality:
        """Assess DONKI data quality"""
        flags = []
        total_records = len(self.flares) + len(self.cmes) + len(self.geomagnetic_storms)
        if not self.donki_available:
            return DataQuality(source="NASA DONKI", completeness=0.0, freshness=0.0,
                               reliability=0.0, record_count=0, data_gaps=0,
                               flags=["UNAVAILABLE: " + "; ".join(self.donki_errors)])

        completeness = min(100.0, total_records / 60 * 100)
        freshness = 50.0 if total_records > 0 else 0.0
        if total_records == 0:
            flags.append("No recent events")

        reliability = (completeness * 0.6 + freshness * 0.4)

        return DataQuality(
            source="NASA DONKI", completeness=completeness, freshness=freshness,
            reliability=reliability, record_count=total_records, data_gaps=0,
            flags=flags if flags else ["Data may be stale"]
        )

    def get_forecast_outlook(self) -> Dict:
        kp_values = [(parse_swpc_time(r.get('time_tag')), as_float(r.get('kp'))) for r in self.kp_forecast]
        kp_values = [(t, max(0.0, min(9.0, kp))) for t, kp in kp_values if t]
        peak_time, peak_kp = max(kp_values, key=lambda x: x[1]) if kp_values else (None, 0.0)
        level = 'WARNING' if peak_kp >= 7 else 'WATCH' if peak_kp >= 5 else 'NORMAL'
        reason = (f"Forecast Kp reaches {peak_kp:.1f} at {peak_time.isoformat()}" if peak_time else
                  "No usable Kp forecast")
        return {'level': level, 'peak_kp': peak_kp, 'peak_time': peak_time, 'reason': reason}

    def estimate_cme_arrival_window(self, cme: CME) -> Optional[Dict]:
        """Return a configurable screening arrival window for an Earth-directed CME."""
        if not cme.is_earth_directed or not cme.start_time or not cme.speed or cme.speed <= 0:
            return None
        eta = self.estimate_cme_eta(cme)
        if eta is None:
            return None
        if cme.estimated_arrival:
            uncertainty_hours, method = 6.0, 'DONKI/WSA-Enlil arrival'
        elif cme.speed >= 1500:
            uncertainty_hours, method = 8.0, 'Drag-based screening estimate'
        elif cme.speed >= 900:
            uncertainty_hours, method = 10.0, 'Drag-based screening estimate'
        else:
            uncertainty_hours, method = 14.0, 'Drag-based screening estimate'
        return {
            'eta': eta,
            'lower': eta - timedelta(hours=uncertainty_hours),
            'upper': eta + timedelta(hours=uncertainty_hours),
            'uncertainty_hours': uncertainty_hours,
            'method': method,
            'transit_hours': (eta-cme.start_time).total_seconds()/3600.0,
            'assumption': 'Configurable screening range, not a validated confidence interval',
        }

    def get_historical_analogs(self, top_n: int = 3) -> List[Dict]:
        """Return normalized storm-pattern analogs when current conditions are disturbed."""
        current = self.get_current_conditions()
        values = {
            'kp': as_float(current['geomagnetic'].get('kp'), float('nan')),
            'dst': as_float(current['geomagnetic'].get('dst'), float('nan')),
            'speed': as_float(current['solar_wind'].get('speed'), float('nan')),
            'bz': as_float(current['solar_wind'].get('bz'), float('nan')),
        }
        if (not math.isfinite(values['kp']) or not math.isfinite(values['dst']) or
                (values['kp'] < 5.0 and values['dst'] > -50.0)):
            return []
        if all(not math.isfinite(value) for value in values.values()):
            return []
        scales = {'kp':9.0,'dst':500.0,'speed':1200.0,'bz':50.0}
        weights = {'kp':0.35,'dst':0.30,'speed':0.20,'bz':0.15}
        scored=[]
        for event in HISTORICAL_STORM_CATALOG:
            distance=0.0; total=0.0; compared=[]
            for feature,weight in weights.items():
                observed=values.get(feature); reference=event.get(feature)
                if reference is None or observed is None or not math.isfinite(observed):
                    continue
                difference=min(1.0,abs(observed-float(reference))/scales[feature])
                distance += weight*difference; total += weight; compared.append(feature)
            if total == 0:
                continue
            similarity=max(0.0,100.0*(1.0-distance/total))
            scored.append({**event,'similarity':round(similarity,1),
                           'compared_features':compared,
                           'disclaimer':'Pattern similarity, not an impact forecast'})
        return sorted(scored,key=lambda item:item['similarity'],reverse=True)[:max(0,top_n)]

    def get_multispacecraft_comparison(self, tolerance_seconds: int = 90) -> Dict:
        """Return the latest solar-wind values from every available RTSW source.

        The tolerance is retained as metadata for later nearest-time matching;
        this latest-sample summary does not imply simultaneous measurements.
        """
        if not self.solar_wind_data:
            return {}
        latest_by_source = {}
        for row in self.solar_wind_data:
            source = row.source or 'Unknown'
            if source not in latest_by_source or row.timestamp > latest_by_source[source].timestamp:
                latest_by_source[source] = row
        now = datetime.now(timezone.utc)
        return {
            source: {
                'timestamp': data.timestamp.isoformat(),
                'age_seconds': max(0.0, (now-data.timestamp).total_seconds()),
                'speed': data.speed, 'density': data.density,
                'temperature': data.temperature, 'bz': data.bz, 'bt': data.bt,
                'dynamic_pressure': data.dynamic_pressure,
                'coupling': data.coupling, 'active': data.active,
                'matching_tolerance_seconds': tolerance_seconds,
            }
            for source, data in latest_by_source.items()
        }

    def get_current_conditions(self) -> Dict:
        """Get current space weather conditions"""
        now = datetime.now(timezone.utc)

        current_xray = None
        current_xray_class = "N/A"
        peak_24h_xray = None
        peak_24h_class = "N/A"
        avg_24h_xray = 0.0

        if self.xray_data:
            recent = [x for x in self.xray_data
                      if (now - x.timestamp).total_seconds() < 1800]
            if not recent:
                recent = self.xray_data[-1:]
            if recent:
                current_xray = recent[-1].flux_long
                current_xray_class = self._flux_to_class(current_xray)

            last_24h = [x for x in self.xray_data
                        if (now - x.timestamp).total_seconds() < 86400]
            if last_24h:
                peak_24h_xray = max(x.flux_long for x in last_24h)
                peak_24h_class = self._flux_to_class(peak_24h_xray)
                avg_24h_xray = sum(x.flux_long for x in last_24h) / len(last_24h)

        xray_trend = "Stable"
        if self.xray_data and len(self.xray_data) >= 60:
            recent_avg = sum(x.flux_long for x in self.xray_data[-30:]) / 30
            older_avg = sum(x.flux_long for x in self.xray_data[-60:-30]) / 30
            if older_avg > 0:
                if recent_avg > older_avg * 1.5:
                    xray_trend = "Rising"
                elif recent_avg < older_avg * 0.67:
                    xray_trend = "Falling"

        current_proton_10 = 0.0
        current_proton_50 = 0.0
        current_proton_100 = 0.0
        peak_72h_proton = 0.0

        if self.proton_data:
            recent = [p for p in self.proton_data
                      if (now - p.timestamp).total_seconds() < 1800]
            if not recent:
                recent = self.proton_data[-1:]
            if recent:
                current_proton_10 = recent[-1].flux_10mev
                current_proton_50 = recent[-1].flux_50mev
                current_proton_100 = recent[-1].flux_100mev

            last_72h = [p for p in self.proton_data
                        if (now - p.timestamp).total_seconds() < 259200]
            if last_72h:
                peak_72h_proton = max(p.flux_10mev for p in last_72h)

        current_sw_speed = 0.0
        current_sw_density = 0.0
        current_sw_temp = 0.0
        current_bz = 0.0
        current_bt = 0.0
        current_bx = 0.0
        current_by = 0.0
        current_coupling = float('nan')
        sw_source = "No data"

        if self.solar_wind_data:
            latest = self.solar_wind_data[-1]
            current_sw_speed = latest.speed
            current_sw_density = latest.density
            current_sw_temp = latest.temperature
            current_bz = latest.bz
            current_bt = latest.bt
            current_bx = latest.bx if latest.bx is not None else 0.0
            current_by = latest.by if latest.by is not None else 0.0
            current_coupling = latest.coupling
            sw_source = latest.source

        current_kp = 0.0
        max_24h_kp = 0.0
        min_24h_kp = 9.0

        if self.kp_data:
            current_kp = self.kp_data[-1].get('kp', 0.0)
            for kp in self.kp_data[-8:]:
                kp_val = kp.get('kp', 0.0)
                max_24h_kp = max(max_24h_kp, kp_val)
                min_24h_kp = min(min_24h_kp, kp_val)
        else:
            min_24h_kp = 0.0

        current_dst = 0.0
        if self.dst_data:
            current_dst = self.dst_data[-1].get('dst', 0.0)

        s_scale = self._proton_to_s_scale(current_proton_10)
        proton_storm = current_proton_10 >= 10
        g_scale = self._kp_to_g_scale(current_kp)
        r_scale = self._flux_to_r_scale(current_xray or 0.0)

        if current_bz <= -10 and current_sw_speed >= 500:
            geoeffectiveness = "High"
        elif current_bz <= -5 or current_sw_speed >= 450:
            geoeffectiveness = "Moderate"
        elif current_bz < 0:
            geoeffectiveness = "Low"
        else:
            geoeffectiveness = "Very Low"

        return {
            'xray': {
                'current_flux': current_xray,
                'classification': current_xray_class,
                'r_scale': r_scale,
                'peak_24h': peak_24h_xray,
                'peak_24h_class': peak_24h_class,
                'avg_24h': avg_24h_xray,
                'trend': xray_trend
            },
            'protons': {
                'flux_10mev': current_proton_10,
                'flux_50mev': current_proton_50,
                'flux_100mev': current_proton_100,
                's_scale': s_scale,
                'storm_active': proton_storm,
                'peak_72h': peak_72h_proton
            },
            'solar_wind': {
                'speed': current_sw_speed,
                'density': current_sw_density,
                'temperature': current_sw_temp,
                'bz': current_bz,
                'bt': current_bt,
                'bx': current_bx,
                'by': current_by,
                'coupling': current_coupling,
                'geoeffectiveness': geoeffectiveness,
                'source': sw_source
            },
            'geomagnetic': {
                'kp': current_kp,
                'g_scale': g_scale,
                'dst': current_dst,
                'max_24h_kp': max_24h_kp,
                'min_24h_kp': min_24h_kp
            }
        }

    @staticmethod
    def auroral_boundary_latitude(kp: float) -> float:
        """Return a bounded Kp-derived screening estimate in geomagnetic degrees."""
        kp = max(0.0, min(9.0, as_float(kp)))
        return max(40.0, min(70.0, 67.0 - 2.5 * kp))

    @staticmethod
    def _latest_before(records: List, stamp: datetime, time_getter) -> Optional[Any]:
        """Return the latest valid record at or before a grid time."""
        eligible = [r for r in records if time_getter(r) and time_getter(r) <= stamp]
        return max(eligible, key=time_getter) if eligible else None

    def build_risk_timeline(self, hours_back: int = 72, hours_forward: int = 48,
                            step_hours: int = 3) -> List[Dict]:
        """Return historical and forecast risk points without inventing forecasts.

        Historical points use last observation carried forward. Future points
        contain geomagnetic risk from Kp forecast and an X-ray screening risk
        from the official flare probabilities. Proton and solar-wind forecasts
        remain None because no dedicated forecast product is loaded.
        """
        if not HAS_NUMPY and hours_forward > 0:
            print("  NumPy unavailable - risk timeline limited to historical data only.")
            hours_forward = 0
        if not any((self.xray_data, self.proton_data, self.solar_wind_data,
                    self.kp_data, self.kp_forecast, self.flare_probabilities)):
            return []
        now = datetime.now(timezone.utc).replace(minute=0, second=0, microsecond=0)
        start = now - timedelta(hours=hours_back)
        points = []
        kp_rows = [(parse_swpc_time(r.get('time_tag')), r) for r in self.kp_data]
        for index in range(int(hours_back / step_hours) + 1):
            stamp = start + timedelta(hours=index * step_hours)
            xr = self._latest_before(self.xray_data, stamp, lambda r: r.timestamp)
            pr = self._latest_before(self.proton_data, stamp, lambda r: r.timestamp)
            sw = self._latest_before(self.solar_wind_data, stamp, lambda r: r.timestamp)
            candidates = [(t, r) for t, r in kp_rows if t and t <= stamp]
            kp = as_float(max(candidates, key=lambda x:x[0])[1].get('kp')) if candidates else 0.0
            xscore,_ = self.risk_engine.calculate_xray_risk(xr.flux_long if xr else 0.0,
                                                             self._flux_to_class(xr.flux_long) if xr else 'N/A')
            pscore,_ = self.risk_engine.calculate_proton_risk(pr.flux_10mev if pr else 0.0)
            gscore,_ = self.risk_engine.calculate_geomagnetic_risk(kp)
            sscore,_ = self.risk_engine.calculate_solar_wind_risk(
                sw.speed if sw else 0.0, sw.bz if sw and math.isfinite(sw.bz) else 0.0,
                sw.density if sw else 0.0)
            composite = round(0.30*xscore + 0.25*pscore + 0.25*gscore + 0.20*sscore)
            points.append({'timestamp':stamp,'kind':'historical','xray':xscore,'proton':pscore,
                           'geomagnetic':gscore,'solar_wind':sscore,'composite':composite})
        mprob = as_float(get_key(self.flare_probabilities, 'm_class_1_day', 'm_class', 'm'))
        xprob = as_float(get_key(self.flare_probabilities, 'x_class_1_day', 'x_class', 'x'))
        flare_screen = min(100.0, 0.6*mprob + 1.0*xprob)
        forecast_rows = [(parse_swpc_time(r.get('time_tag')), r) for r in self.kp_forecast]
        for index in range(1, int(hours_forward / step_hours) + 1):
            stamp = now + timedelta(hours=index*step_hours)
            nearest = min(((abs((t-stamp).total_seconds()),r) for t,r in forecast_rows if t), default=None)
            if nearest and nearest[0] <= step_hours*3600*1.6:
                kp = max(0.0,min(9.0,as_float(nearest[1].get('kp'))))
                gscore,_ = self.risk_engine.calculate_geomagnetic_risk(kp)
            else:
                gscore = None
            known = [v for v in (flare_screen, gscore) if v is not None]
            composite = round(sum(known)/len(known)) if known else None
            points.append({'timestamp':stamp,'kind':'forecast','xray':flare_screen,
                           'proton':None,'geomagnetic':gscore,'solar_wind':None,
                           'composite':composite})
        return points

    def risk_trend_24h(self) -> Dict:
        rows = [r for r in self.build_risk_timeline(24, 0, 3)
                if r['kind'] == 'historical' and r['composite'] is not None]
        if len(rows) < 5:
            return {'label': 'INSUFFICIENT DATA', 'slope': None, 'minimum': None,
                    'maximum': None, 'current': None, 'points': rows}
        values = [r['composite'] for r in rows]
        if not HAS_NUMPY:
            return {'label': 'NUMPY UNAVAILABLE', 'slope': None,
                    'minimum': min(values), 'maximum': max(values),
                    'current': values[-1], 'points': rows}
        x = np.arange(len(rows), dtype=float)
        y = np.array(values, dtype=float)
        slope = float(np.polyfit(x, y, 1)[0]) if len(y) > 1 and np.ptp(y) > 0 else 0.0
        label = 'RISING' if slope > 1.0 else 'FALLING' if slope < -1.0 else 'STABLE'
        return {'label': label, 'slope': slope,
                'minimum': float(y.min()), 'maximum': float(y.max()),
                'current': float(y[-1]), 'points': rows}

    def get_recent_events(self, hours: int = 72) -> Dict:
        """Get summary of recent events"""
        now = datetime.now(timezone.utc)
        cutoff = now - timedelta(hours=hours)

        recent_flares = [f for f in self.flares if f.start_time >= cutoff]

        flare_counts = {'X': 0, 'M': 0, 'C': 0, 'B': 0, 'A': 0}
        significant_flares = []

        for flare in recent_flares:
            class_letter = flare.class_type[0].upper() if flare.class_type else 'A'
            if class_letter in flare_counts:
                flare_counts[class_letter] += 1
            if class_letter in ('X', 'M'):
                significant_flares.append(flare)

        recent_cmes = [c for c in self.cmes if c.start_time >= cutoff]
        earth_directed_cmes = [c for c in recent_cmes if c.is_earth_directed]

        cme_stats = {
            'total': len(recent_cmes),
            'earth_directed': len(earth_directed_cmes),
            'avg_speed': (sum(c.speed for c in recent_cmes) / len(recent_cmes)
                          if recent_cmes else 0.0),
            'max_speed': max((c.speed for c in recent_cmes), default=0.0),
            'min_speed': min((c.speed for c in recent_cmes), default=0.0)
        }

        recent_storms = [s for s in self.geomagnetic_storms if s.start_time >= cutoff]

        return {
            'flares': {
                'total': len(recent_flares),
                'by_class': flare_counts,
                'significant': significant_flares,
                'all': recent_flares
            },
            'cmes': {
                'stats': cme_stats,
                'earth_directed': earth_directed_cmes,
                'all': recent_cmes
            },
            'geomagnetic_storms': recent_storms
        }

    def get_threats(self, hours_forward: int = 48) -> List[str]:
        """Identify current and upcoming threats"""
        threats = []
        now = datetime.now(timezone.utc)

        recent_flares = [f for f in self.flares
                         if (now - f.start_time).total_seconds() < 86400
                         and str(f.class_type).upper().startswith('X')]
        if recent_flares:
            threats.append(f"{len(recent_flares)} X-class flare(s) in past 24 hours")

        for cme in self.cmes:
            if not cme.is_earth_directed:
                continue

            eta = self.estimate_cme_eta(cme)
            if eta is None:
                continue

            hours_until = (eta - now).total_seconds() / 3600
            if 0 < hours_until <= hours_forward:
                threats.append(
                    f"Earth-directed CME arrival in ~{int(hours_until)} hours "
                    f"({int(cme.speed)} km/s)"
                )

        if self.proton_data:
            recent_protons = [p for p in self.proton_data
                              if (now - p.timestamp).total_seconds() < 3600]
            if recent_protons:
                max_proton = max(p.flux_10mev for p in recent_protons)
                if max_proton >= 10:
                    threats.append(
                        f"Elevated proton flux: {max_proton:.1f} pfu "
                        f"(S{self._proton_to_s_scale(max_proton)} storm)"
                    )

        if self.kp_data:
            current_kp = self.kp_data[-1].get('kp', 0.0)
            if current_kp >= 5:
                threats.append(
                    f"Active geomagnetic storm: Kp={current_kp} "
                    f"(G{self._kp_to_g_scale(current_kp)})"
                )

        for forecast in self.kp_forecast[:12]:
            kp = forecast.get('kp', 0.0)
            if kp >= 5:
                threats.append(
                    f"Forecast geomagnetic storm: Kp={kp} at "
                    f"{forecast.get('time_tag', 'unknown')}"
                )
                break

        if self.solar_wind_data:
            latest = self.solar_wind_data[-1]
            if latest.speed >= 600:
                threats.append(f"High-speed solar wind stream: {latest.speed:.0f} km/s")
            if latest.bz <= -10:
                threats.append(f"Strongly southward IMF: Bz={latest.bz:.1f} nT")

        return threats

    def estimate_cme_eta(self, cme: CME) -> Optional[datetime]:
        '''Predicted L1 arrival for a CME, using its Enlil time if given.

        Drag-corrected transit time. The constant-speed 1 AU / v form is
        biased in opposite directions at the two ends of the speed range,
        so it is not used. The model below is dimensionally consistent
        and bounded by the ambient wind in both directions:

          d      = 1 AU - 1.5e6 km, the Sun to L1 path
          w      = 400 km/s ambient solar wind
          u0     = v0 - w
          t_est  = d / ((v0 + w) / 2)
          v_eff  = w + u0 / (1 + gamma |u0| t_est)

        gamma is 1e-7 km^-1, the standard drag parameter. A CME faster
        than the ambient wind is decelerated toward w; a slower one is
        dragged up toward w.
        '''
        if cme.estimated_arrival:
            return cme.estimated_arrival
        if not cme.start_time or not cme.speed or cme.speed <= 0:
            return None

        distance_km = 1.496e8 - 1.5e6
        ambient = 400.0
        gamma = 1.0e-7  # km^-1, typical drag parameter

        u0 = cme.speed - ambient
        v_mean = max(0.5 * (cme.speed + ambient), 200.0)
        t_est_seconds = distance_km / v_mean

        denom = 1.0 + gamma * abs(u0) * t_est_seconds
        v_eff = ambient + u0 / denom
        v_eff = max(v_eff, 200.0)

        travel_time_hours = (distance_km / v_eff) / 3600.0
        return cme.start_time + timedelta(hours=travel_time_hours)

    def _flux_to_class(self, flux: float) -> str:
        """Convert X-ray flux to flare classification"""
        if not flux or flux <= 0:
            return "N/A"

        if flux >= 1e-4:
            return f"X{flux / 1e-4:.1f}"
        elif flux >= 1e-5:
            return f"M{flux / 1e-5:.1f}"
        elif flux >= 1e-6:
            return f"C{flux / 1e-6:.1f}"
        elif flux >= 1e-7:
            return f"B{flux / 1e-7:.1f}"
        else:
            return f"A{flux / 1e-8:.1f}"

    def _flux_to_r_scale(self, flux: float) -> Tuple[int, str]:
        """Convert X-ray flux to NOAA R-scale"""
        if flux >= 2e-3:
            return 5, "R5 (Extreme)"
        elif flux >= 1e-3:
            return 4, "R4 (Severe)"
        elif flux >= 1e-4:
            return 3, "R3 (Strong)"
        elif flux >= 5e-5:
            return 2, "R2 (Moderate)"
        elif flux >= 1e-5:
            return 1, "R1 (Minor)"
        return 0, "R0 (None)"

    def _proton_to_s_scale(self, flux_10mev: float) -> int:
        """Convert proton flux to NOAA S-scale"""
        if flux_10mev >= 100000:
            return 5
        elif flux_10mev >= 10000:
            return 4
        elif flux_10mev >= 1000:
            return 3
        elif flux_10mev >= 100:
            return 2
        elif flux_10mev >= 10:
            return 1
        return 0

    def _kp_to_g_scale(self, kp: float) -> int:
        """Convert Kp index to NOAA G-scale"""
        if kp >= 9:
            return 5
        elif kp >= 8:
            return 4
        elif kp >= 7:
            return 3
        elif kp >= 6:
            return 2
        elif kp >= 5:
            return 1
        return 0


# ============================================================================
# VISUALISATION LAYER
# ============================================================================

class SpaceWeatherVisualizer:
    """Builds figures, collects imagery, and writes the visual report"""

    PALETTE = {
        'paper': '#EDEFF2',
        'panel': '#F9FAFB',
        'ink': '#101A2B',
        'muted': '#5A6779',
        'rule': '#C7CEDA',
        'primary': '#1B3A6B',
        'secondary': '#2E7D74',
        'tertiary': '#8A5A2B',
        'accent': '#7A3E8F',
    }

    SCALE_COLORS = ['#3F7D3A', '#B9A200', '#D98B12', '#C4551F',
                    '#A32B22', '#6E1414']

    def __init__(self, aggregator: SpaceWeatherAggregator,
                 output_dir: str = "swrl_report",
                 dpi: int = DEFAULT_OUTPUT_DPI,
                 include_images: bool = True,
                 output_width: int = DEFAULT_OUTPUT_WIDTH,
                 output_height: int = DEFAULT_OUTPUT_HEIGHT):
        self.agg = aggregator
        self.api = aggregator.api
        self.output_dir = output_dir
        self.figure_dir = os.path.join(output_dir, "figures")
        self.image_dir = os.path.join(output_dir, "images")
        self.fits_dir = os.path.join(output_dir, "fits")
        self.dpi = dpi
        self.include_images = include_images
        self.output_width = int(output_width)
        self.output_height = int(output_height)
        if self.output_width <= 0 or self.output_height <= 0:
            raise ValueError("Output dimensions must be positive integers")

        self.figures: List[Dict[str, str]] = []
        self.images: List[Dict[str, str]] = []
        self.unavailable_figures: List[Dict[str, str]] = []

        for directory in (self.output_dir, self.figure_dir, self.image_dir, self.fits_dir):
            os.makedirs(directory, exist_ok=True)

    # ------------------------------------------------------------------
    # Style and small helpers
    # ------------------------------------------------------------------

    def _apply_style(self):
        """Set the rcParams once per figure batch"""
        plt.rcParams.update({
            'figure.facecolor': self.PALETTE['paper'],
            'savefig.facecolor': self.PALETTE['paper'],
            'axes.facecolor': self.PALETTE['panel'],
            'axes.edgecolor': self.PALETTE['rule'],
            'axes.labelcolor': self.PALETTE['ink'],
            'axes.titlecolor': self.PALETTE['ink'],
            'axes.titlesize': 10,
            'axes.titleweight': 'bold',
            'axes.labelsize': 9,
            'axes.linewidth': 0.8,
            'axes.grid': True,
            'axes.axisbelow': True,
            'grid.color': self.PALETTE['rule'],
            'grid.linewidth': 0.5,
            'grid.alpha': 0.8,
            'text.color': self.PALETTE['ink'],
            'xtick.color': self.PALETTE['muted'],
            'ytick.color': self.PALETTE['muted'],
            'xtick.labelsize': 8,
            'ytick.labelsize': 8,
            'legend.fontsize': 8,
            'legend.framealpha': 0.9,
            'legend.facecolor': self.PALETTE['panel'],
            'legend.edgecolor': self.PALETTE['rule'],
            'font.size': 9,
            'figure.dpi': self.dpi,
            'timezone': 'UTC',
        })


    def _has_numpy(self) -> bool:
        """Return whether NumPy is available to this visualizer instance."""
        return HAS_NUMPY

    def _time_axis(self, ax, mark_now: bool = True):
        """Format a datetime x-axis and optionally mark the current time"""
        locator = mdates.AutoDateLocator(minticks=4, maxticks=9)
        ax.xaxis.set_major_locator(locator)
        ax.xaxis.set_major_formatter(
            mdates.ConciseDateFormatter(locator, tz=timezone.utc))
        if mark_now:
            ax.axvline(datetime.now(timezone.utc), color=self.PALETTE['ink'],
                       lw=0.8, ls=(0, (4, 3)), alpha=0.55, zorder=1)

    def _image_metrics(self, path: str, threshold: int = 12) -> Dict:
        if not HAS_PIL or not HAS_NUMPY:
            return {}
        with Image.open(path) as image:
            rgb = np.asarray(image.convert('RGB'))
            signal = np.max(rgb, axis=2) > threshold
            return {
                'width': int(image.width),
                'height': int(image.height),
                'science_fill_percent': round(float(signal.mean() * 100.0), 1),
            }

    def _crop_science_content(self, path: str, threshold: int = 12,
                              padding_fraction: float = 0.04) -> str:
        """Crop broad empty borders while retaining the main solar/coronal field.

        Rows and columns must contain a meaningful fraction of non-background
        pixels. This rejects tiny footer text and avoids the small-disk result
        produced by merely placing a square quicklook on a 16:9 canvas.
        """
        if not HAS_PIL or not getattr(self, '_has_numpy', lambda: False)():
            return path
        with Image.open(path) as source:
            rgb = source.convert('RGB')
            array = np.asarray(rgb)
            signal = np.max(array, axis=2) > threshold
            min_row_pixels = max(4, int(array.shape[1] * 0.01))
            min_col_pixels = max(4, int(array.shape[0] * 0.01))
            ys = np.where(signal.sum(axis=1) >= min_row_pixels)[0]
            xs = np.where(signal.sum(axis=0) >= min_col_pixels)[0]
            if not len(xs) or not len(ys):
                return path
            left, right = int(xs[0]), int(xs[-1]) + 1
            top, bottom = int(ys[0]), int(ys[-1]) + 1
            pad_x = int((right - left) * padding_fraction)
            pad_y = int((bottom - top) * padding_fraction)
            box = (max(0, left-pad_x), max(0, top-pad_y),
                   min(rgb.width, right+pad_x), min(rgb.height, bottom+pad_y))
            cropped = rgb.crop(box)
            suffix = Path(path).suffix.lower()
            if suffix in ('.jpg', '.jpeg'):
                cropped.save(path, 'JPEG', quality=95, subsampling=0, optimize=True)
            else:
                cropped.save(path, 'PNG', optimize=True)
        return path

    def _normalize_image_2k(self, path: str, background=None) -> str:
        """Normalize an image to exactly 2560 x 1440 without distortion."""
        if not HAS_PIL:
            raise RuntimeError(
                "Pillow is required for 2K image normalization. "
                "Install with: pip install Pillow"
            )
        background = background or self.PALETTE['paper']
        with Image.open(path) as source:
            source = source.convert('RGB')
            # Scale both down and up so the main science content fills the
            # 2K frame. thumbnail() only shrinks and was the reason small
            # source disks stayed small on a large black canvas.
            scale = min(self.output_width / source.width,
                        self.output_height / source.height)
            target_size = (max(1, int(round(source.width * scale))),
                           max(1, int(round(source.height * scale))))
            source = source.resize(target_size, Image.Resampling.LANCZOS)
            canvas = Image.new('RGB', (self.output_width, self.output_height), background)
            left = (self.output_width - source.width) // 2
            top = (self.output_height - source.height) // 2
            canvas.paste(source, (left, top))
            suffix = os.path.splitext(path)[1].lower()
            if suffix in ('.jpg', '.jpeg'):
                canvas.save(path, format='JPEG', quality=95, subsampling=0, optimize=True)
            else:
                canvas.save(path, format='PNG', optimize=True)
        return path

    def _save(self, fig, key: str, title: str, caption: str) -> Optional[str]:
        """Write a figure to disk and register it for the report"""
        try:
            path = os.path.join(self.figure_dir, f"{key}.png")
            fig.set_size_inches(self.output_width / self.dpi,
                                self.output_height / self.dpi, forward=True)
            try:
                fig.tight_layout()
            except Exception:
                pass
            fig.savefig(path, dpi=self.dpi, bbox_inches=None, pad_inches=0,
                        facecolor=fig.get_facecolor())
            plt.close(fig)
            self._normalize_image_2k(path)
            self.figures.append({'key': key, 'title': title,
                                 'caption': caption, 'path': path})
            print(f"  Figure written: {path}")
            return path
        except Exception as e:
            print(f"  Could not save figure {key}: {e}")
            try:
                plt.close(fig)
            except Exception:
                pass
            return None

    # ------------------------------------------------------------------
    # Figure 1 - GOES X-ray flux
    # ------------------------------------------------------------------

    def plot_xray(self) -> Optional[str]:
        """GOES soft X-ray flux with the A-X classification bands"""
        if not HAS_MATPLOTLIB or not self.agg.xray_data:
            return None

        data = self.agg.xray_data
        times = [d.timestamp for d in data]
        long_channel = [blank_if_zero(d.flux_long) for d in data]
        short_channel = [blank_if_zero(d.flux_short) for d in data]

        fig, ax = plt.subplots(figsize=(9.5, 4.4))

        bands = [(1e-8, 1e-7, 0, 0.05), (1e-7, 1e-6, 0, 0.05),
                 (1e-6, 1e-5, 1, 0.09), (1e-5, 1e-4, 3, 0.13),
                 (1e-4, 1e-2, 5, 0.18)]
        for lower, upper, severity, shade in bands:
            ax.axhspan(lower, upper, color=self.SCALE_COLORS[severity],
                       alpha=shade, zorder=0)
            ax.axhline(lower, color=self.PALETTE['rule'], lw=0.6, zorder=0)

        ax.plot(times, long_channel, lw=1.3, color=self.PALETTE['primary'],
                label='0.1-0.8 nm (long, classification channel)')
        ax.plot(times, short_channel, lw=0.9, color=self.PALETTE['tertiary'],
                alpha=0.85, label='0.05-0.4 nm (short)')

        ax.set_yscale('log')
        ax.set_ylim(1e-9, 1e-3)
        ax.set_ylabel('X-ray irradiance  [W m$^{-2}$]')
        ax.set_xlabel('Time (UTC)')
        ax.set_title('GOES soft X-ray flux')
        ax.legend(loc='upper left', ncol=2)
        self._time_axis(ax)

        letters = ax.twinx()
        letters.set_yscale('log')
        letters.set_ylim(ax.get_ylim())
        letters.set_yticks([3.16e-9, 3.16e-8, 3.16e-7, 3.16e-6,
                            3.16e-5, 3.16e-4])
        letters.set_yticklabels(['', 'A', 'B', 'C', 'M', 'X'])
        letters.tick_params(length=0, labelsize=10, colors=self.PALETTE['ink'])
        letters.grid(False)

        try:
            peak = max((d for d in data if d.flux_long > 0),
                       key=lambda d: d.flux_long)
            ax.annotate(f"peak {self.agg._flux_to_class(peak.flux_long)}",
                        xy=(peak.timestamp, peak.flux_long),
                        xytext=(0, 16), textcoords='offset points',
                        ha='center', fontsize=8, color=self.PALETTE['ink'],
                        arrowprops=dict(arrowstyle='-', lw=0.8,
                                        color=self.PALETTE['muted']))
        except ValueError:
            pass

        return self._save(
            fig, 'xray_flux', 'GOES soft X-ray flux',
            'Long channel in the classification band; the shaded decades are '
            'the A to X classes. A flare is the impulsive rise followed by a '
            'slower thermal decay, so a trace still high on the decay is a '
            'recent event rather than a new one.')

    # ------------------------------------------------------------------
    # Figure 2 - GOES integral proton flux
    # ------------------------------------------------------------------

    def plot_protons(self) -> Optional[str]:
        """GOES integral proton flux with the S-scale thresholds"""
        if not HAS_MATPLOTLIB or not self.agg.proton_data:
            return None

        data = self.agg.proton_data
        times = [d.timestamp for d in data]

        fig, ax = plt.subplots(figsize=(9.5, 4.2))

        channels = [
            ('>=10 MeV', [blank_if_zero(d.flux_10mev) for d in data],
             self.PALETTE['primary'], 1.3),
            ('>=50 MeV', [blank_if_zero(d.flux_50mev) for d in data],
             self.PALETTE['secondary'], 1.0),
            ('>=100 MeV', [blank_if_zero(d.flux_100mev) for d in data],
             self.PALETTE['accent'], 1.0),
        ]
        for label, series, color, width in channels:
            ax.plot(times, series, lw=width, color=color, label=label)

        for threshold, level in ((10, 1), (100, 2), (1000, 3),
                                 (10000, 4), (100000, 5)):
            ax.axhline(threshold, color=self.SCALE_COLORS[level], lw=0.8,
                       ls='--', alpha=0.85)
            ax.text(0.985, threshold, f'S{level}', transform=ax.get_yaxis_transform(),
                    ha='right', va='bottom', fontsize=8,
                    color=self.SCALE_COLORS[level])

        ax.set_yscale('log')
        ax.set_ylim(1e-2, 1e6)
        ax.set_ylabel('Integral flux  [pfu]  (protons cm$^{-2}$ s$^{-1}$ sr$^{-1}$)')
        ax.set_title('GOES energetic proton environment')
        ax.legend(loc='upper left', ncol=3)
        self._time_axis(ax)

        return self._save(
            fig, 'proton_flux', 'GOES energetic proton environment',
            'Dashed lines are the NOAA S-scale thresholds on the >=10 MeV '
            'channel. A hard event shows the >=100 MeV channel rising with '
            'the others, which is the population that reaches aircraft '
            'altitude on polar routes.')

    # ------------------------------------------------------------------
    # Figure 3 - RTSW solar wind stack
    # ------------------------------------------------------------------

    def plot_solar_wind(self) -> Optional[str]:
        """Five-panel L1 solar wind stack including the Newell coupling"""
        if not HAS_MATPLOTLIB or not self.agg.solar_wind_data:
            return None

        data = self.agg.solar_wind_data
        times = [d.timestamp for d in data]
        source = self.agg.solar_wind_data[-1].source

        fig, axes = plt.subplots(5, 1, figsize=(9.5, 11.5), sharex=True,
                                 gridspec_kw={'hspace': 0.12})

        speed = [blank_if_zero(d.speed) for d in data]
        axes[0].plot(times, speed, lw=1.1, color=self.PALETTE['primary'])
        finite_speed = [v for v in speed if v == v]
        speed_ceiling = max(finite_speed) if finite_speed else 0.0
        for level, color_index, label in ((500, 1, 'enhanced'),
                                          (600, 2, 'high speed stream'),
                                          (800, 4, 'very high speed')):
            if level > speed_ceiling * 1.12:
                continue
            axes[0].axhline(level, color=self.SCALE_COLORS[color_index],
                            lw=0.8, ls='--', alpha=0.8)
            axes[0].text(0.985, level, label,
                         transform=axes[0].get_yaxis_transform(),
                         ha='right', va='bottom', fontsize=7,
                         color=self.SCALE_COLORS[color_index])
        axes[0].set_ylabel('$v$  [km s$^{-1}$]')
        axes[0].set_title(f'Solar wind at L1  ({source})')

        density = [blank_if_zero(d.density) for d in data]
        axes[1].plot(times, density, lw=1.0, color=self.PALETTE['secondary'])
        axes[1].set_ylabel('$n_p$  [cm$^{-3}$]')

        temperature = [blank_if_zero(d.temperature) for d in data]
        axes[2].plot(times, temperature, lw=1.0, color=self.PALETTE['tertiary'])
        axes[2].set_yscale('log')
        axes[2].set_ylabel('$T_p$  [K]')

        bz = [as_float(d.bz) for d in data]
        bt = [as_float(d.bt) for d in data]
        axes[3].plot(times, bt, lw=0.9, color=self.PALETTE['muted'],
                     label='$B_t$')
        axes[3].plot(times, bz, lw=1.1, color=self.PALETTE['primary'],
                     label='$B_z$ (GSM)')
        axes[3].axhline(0, color=self.PALETTE['ink'], lw=0.8)
        try:
            axes[3].fill_between(times, bz, 0,
                                 where=[value < 0 for value in bz],
                                 color=self.SCALE_COLORS[4], alpha=0.22,
                                 interpolate=True, label='southward IMF')
        except Exception:
            pass
        axes[3].set_ylabel('$B$  [nT]')
        axes[3].legend(loc='upper left', ncol=3)

        coupling = [d.coupling for d in data]
        axes[4].plot(times, coupling, lw=1.0, color=self.PALETTE['accent'])
        axes[4].axhline(4421, color=self.PALETTE['muted'], lw=0.8, ls='--')
        axes[4].text(0.985, 4421, 'long-term average', ha='right', va='bottom',
                     fontsize=7, color=self.PALETTE['muted'],
                     transform=axes[4].get_yaxis_transform())
        axes[4].set_ylabel(r'$d\Phi_{MP}/dt$'
                           '\n'
                           r'[(km s$^{-1}$)$^{4/3}$ nT$^{2/3}$]')
        axes[4].set_xlabel('Time (UTC)')

        for ax in axes:
            self._time_axis(ax)

        return self._save(
            fig, 'solar_wind', f'Solar wind at L1 ({source})',
            'The bottom panel is the Newell coupling function, '
            'v^(4/3) B_T^(2/3) sin^(8/3)(theta_c/2), an empirical merging '
            'rate at the magnetopause. Sustained excursions above its '
            'long-term average predict the geomagnetic response better than '
            'speed or Bz taken alone, and lead the Kp response by roughly '
            'the convection timescale.')

    # ------------------------------------------------------------------
    # Figure 4 - geomagnetic response
    # ------------------------------------------------------------------

    def plot_geomagnetic(self) -> Optional[str]:
        """Observed and forecast Kp, with Dst underneath"""
        if not HAS_MATPLOTLIB:
            return None
        if not self.agg.kp_data and not self.agg.kp_forecast and not self.agg.dst_data:
            return None

        fig, axes = plt.subplots(2, 1, figsize=(9.5, 6.4), sharex=True,
                                 gridspec_kw={'hspace': 0.16,
                                              'height_ratios': [1.15, 1]})

        bar_width = 3.0 / 24.0

        observed_times, observed_values = [], []
        for row in self.agg.kp_data:
            stamp = parse_swpc_time(row.get('time_tag'))
            if stamp is None:
                continue
            observed_times.append(stamp)
            observed_values.append(as_float(row.get('kp')))

        forecast_times, forecast_values = [], []
        for row in self.agg.kp_forecast:
            stamp = parse_swpc_time(row.get('time_tag'))
            if stamp is None:
                continue
            forecast_times.append(stamp)
            forecast_values.append(as_float(row.get('kp')))

        def kp_color(value: float) -> str:
            return self.SCALE_COLORS[self.agg._kp_to_g_scale(value)]

        if observed_times:
            axes[0].bar(observed_times, observed_values, width=bar_width,
                        align='edge',
                        color=[kp_color(v) for v in observed_values],
                        edgecolor=self.PALETTE['panel'], linewidth=0.4)
        if forecast_times:
            axes[0].bar(forecast_times, forecast_values, width=bar_width,
                        align='edge',
                        color=[kp_color(v) for v in forecast_values],
                        alpha=0.45, hatch='///',
                        edgecolor=self.PALETTE['panel'], linewidth=0.4)

        axes[0].axhline(5, color=self.SCALE_COLORS[1], lw=0.9, ls='--')
        axes[0].text(0.985, 5, 'G1 storm threshold', ha='right', va='bottom',
                     fontsize=7, color=self.SCALE_COLORS[1],
                     transform=axes[0].get_yaxis_transform())
        axes[0].set_ylim(0, 9)
        axes[0].set_yticks(range(0, 10))
        axes[0].set_ylabel('$K_p$')
        axes[0].set_title('Geomagnetic activity: observed and forecast')
        axes[0].legend(handles=[
            Patch(facecolor=self.PALETTE['muted'], label='observed'),
            Patch(facecolor=self.PALETTE['muted'], alpha=0.45, hatch='///',
                  label='forecast'),
        ], loc='upper left', ncol=2)

        dst_times, dst_values = [], []
        for row in self.agg.dst_data:
            stamp = parse_swpc_time(row.get('time_tag'))
            if stamp is None:
                continue
            dst_times.append(stamp)
            dst_values.append(as_float(row.get('dst')))

        if dst_times:
            axes[1].plot(dst_times, dst_values, lw=1.2,
                         color=self.PALETTE['primary'])
            axes[1].fill_between(dst_times, dst_values, 0,
                                 where=[v < 0 for v in dst_values],
                                 color=self.PALETTE['primary'], alpha=0.15,
                                 interpolate=True)
            for level, color_index, label in ((-30, 1, 'weak storm'),
                                              (-50, 2, 'moderate'),
                                              (-100, 3, 'intense'),
                                              (-250, 5, 'super storm')):
                axes[1].axhline(level, color=self.SCALE_COLORS[color_index],
                                lw=0.7, ls='--', alpha=0.8)
                axes[1].text(0.985, level, label, ha='right', va='bottom',
                             fontsize=7, color=self.SCALE_COLORS[color_index],
                             transform=axes[1].get_yaxis_transform())
        else:
            axes[1].text(0.5, 0.5, 'Dst unavailable', ha='center', va='center',
                         transform=axes[1].transAxes,
                         color=self.PALETTE['muted'])

        axes[1].axhline(0, color=self.PALETTE['ink'], lw=0.8)
        axes[1].set_ylabel('Dst  [nT]')
        axes[1].set_xlabel('Time (UTC)')

        for ax in axes:
            self._time_axis(ax)

        return self._save(
            fig, 'geomagnetic', 'Geomagnetic activity',
            'Bar colour is the NOAA G-scale; hatched bars are forecast. Dst '
            'below tracks the ring current directly, so a deep excursion '
            'there confirms that a Kp spike was a genuine storm main phase '
            'rather than a single disturbed three-hour interval.')

    # ------------------------------------------------------------------
    # Figure 5 - CME population
    # ------------------------------------------------------------------

    def plot_cmes(self) -> Optional[str]:
        """CME speed against launch time, Earth-directed events marked"""
        if not HAS_MATPLOTLIB or not self.agg.cmes:
            return None

        cmes = self.agg.cmes
        fig, ax = plt.subplots(figsize=(9.5, 4.4))

        def marker_size(cme: CME) -> float:
            half_angle = cme.half_angle if cme.half_angle else 20.0
            return max(25.0, min(420.0, (half_angle ** 1.6) / 2.0))

        other = [c for c in cmes if not c.is_earth_directed]
        earth = [c for c in cmes if c.is_earth_directed]

        if other:
            ax.scatter([c.start_time for c in other], [c.speed for c in other],
                       s=[marker_size(c) for c in other],
                       facecolor='none', edgecolor=self.PALETTE['muted'],
                       linewidth=1.0, label='not Earth-directed')
        if earth:
            ax.scatter([c.start_time for c in earth], [c.speed for c in earth],
                       s=[marker_size(c) for c in earth],
                       facecolor=self.SCALE_COLORS[3], alpha=0.55,
                       edgecolor=self.SCALE_COLORS[4], linewidth=1.0,
                       label='Earth-directed')

        ax.axhline(750, color=self.PALETTE['muted'], lw=0.8, ls='--')
        ax.text(0.985, 750, 'shock-driving regime', ha='right', va='bottom',
                fontsize=7, color=self.PALETTE['muted'],
                transform=ax.get_yaxis_transform())

        now = datetime.now(timezone.utc)
        for cme in earth[:6]:
            eta = self.agg.estimate_cme_eta(cme)
            if not eta:
                continue
            hours = (eta - now).total_seconds() / 3600
            label = (f"ETA +{hours:.0f} h" if hours > 0
                     else f"arrived {abs(hours):.0f} h ago")
            ax.annotate(label, xy=(cme.start_time, cme.speed),
                        xytext=(0, 14), textcoords='offset points',
                        ha='center', fontsize=7.5,
                        color=self.PALETTE['ink'])

        lower, upper = ax.get_ylim()
        ax.set_ylim(lower, upper + (upper - lower) * 0.16)

        ax.set_ylabel('Plane-of-sky speed  [km s$^{-1}$]')
        ax.set_xlabel('Launch time (UTC)')
        ax.set_title('CMEs catalogued by DONKI')
        ax.legend(loc='upper left', markerscale=0.45)
        self._time_axis(ax)

        return self._save(
            fig, 'cme_population', 'CME population',
            'Speeds are the plane-of-sky fits, so an Earth-directed halo is '
            'projected and its true radial speed is higher than plotted. '
            'ETAs use the WSA-Enlil arrival where DONKI supplies one and a '
            'drag relaxation towards a 400 km/s ambient wind otherwise.')

    # ------------------------------------------------------------------
    # Figure 6 - activity and risk overview
    # ------------------------------------------------------------------

    def plot_overview(self, risk: Dict, events: Dict) -> Optional[str]:
        """Flare tally and the weighted risk breakdown side by side"""
        if not HAS_MATPLOTLIB:
            return None

        fig, axes = plt.subplots(1, 2, figsize=(9.5, 3.8),
                                 gridspec_kw={'wspace': 0.42})

        counts = events['flares']['by_class']
        classes = ['A', 'B', 'C', 'M', 'X']
        values = [counts.get(c, 0) for c in classes]
        severity = [0, 0, 1, 3, 5]
        axes[0].bar(classes, values,
                    color=[self.SCALE_COLORS[s] for s in severity],
                    width=0.62)
        for index, value in enumerate(values):
            axes[0].text(index, value, str(value), ha='center', va='bottom',
                         fontsize=9, color=self.PALETTE['ink'])
        axes[0].set_ylabel('events in 72 h')
        axes[0].set_title('Flare tally by class')
        axes[0].set_ylim(0, max(values + [1]) * 1.25)
        axes[0].grid(axis='x', visible=False)

        components = [('X-ray', risk['xray_risk'], 0.30),
                      ('Protons', risk['proton_risk'], 0.25),
                      ('Geomagnetic', risk['geomagnetic_risk'], 0.25),
                      ('Solar wind', risk['solar_wind_risk'], 0.20)]
        labels = [f"{name} x{weight:.2f}" for name, _, weight in components]
        scores = [score for _, score, _ in components]
        positions = list(range(len(components)))

        def risk_color(score: float) -> str:
            if score >= 80:
                return self.SCALE_COLORS[5]
            if score >= 60:
                return self.SCALE_COLORS[4]
            if score >= 40:
                return self.SCALE_COLORS[3]
            if score >= 20:
                return self.SCALE_COLORS[2]
            return self.SCALE_COLORS[0]

        axes[1].barh(positions, scores,
                     color=[risk_color(s) for s in scores], height=0.6)
        axes[1].set_yticks(positions)
        axes[1].set_yticklabels(labels)
        axes[1].invert_yaxis()
        axes[1].set_xlim(0, 112)
        axes[1].set_xlabel('component risk  [0-100]')
        axes[1].set_title(f"Weighted risk: {risk['level']} "
                          f"({risk['overall_risk']}/100)")
        axes[1].axvline(risk['overall_risk'], color=self.PALETTE['ink'],
                        lw=1.2, ls=(0, (4, 3)))
        axes[1].grid(axis='y', visible=False)
        for position, score in zip(positions, scores):
            axes[1].text(score + 1.5, position, str(int(score)),
                         va='center', fontsize=8, color=self.PALETTE['ink'])

        return self._save(
            fig, 'overview', 'Activity and risk overview',
            'The dashed vertical line is the weighted total, so a component '
            'bar reaching past it is what is currently carrying the score.')

    def _unavailable(self, key: str, title: str, reason: str) -> None:
        self.unavailable_figures.append({'key': key, 'title': title, 'reason': reason})

    def plot_cme_arrival_windows(self) -> Optional[str]:
        """Two-panel CME launch and Earth-arrival screening timeline."""
        earth=[c for c in self.agg.cmes if c.is_earth_directed and c.speed>0]
        windows=[(c,self.agg.estimate_cme_arrival_window(c)) for c in earth]
        windows=[item for item in windows if item[1] is not None]
        if not HAS_MATPLOTLIB or not windows:
            self._unavailable('cme_arrival_windows','CME arrival windows',
                              'No Earth-directed CME with a usable arrival estimate was available.')
            return None
        windows=sorted(windows,key=lambda item:item[0].start_time)[:8]
        fig,(launch_ax,arrival_ax)=plt.subplots(2,1,figsize=(10.8,7.0),gridspec_kw={'height_ratios':[1.15,1]})
        launch_ax.scatter([c.start_time for c,w in windows],[c.speed for c,w in windows],
                          s=75,color=self.PALETTE['primary'],edgecolor='white',linewidth=.6)
        for index,(cme,window) in enumerate(windows,1):
            launch_ax.annotate(f'CME {index}',(cme.start_time,cme.speed),xytext=(5,6),
                               textcoords='offset points',fontsize=8)
        launch_ax.set_ylabel('Plane-of-sky speed [km/s]')
        launch_ax.set_title('Earth-directed CME launches')
        self._time_axis(launch_ax,mark_now=False)
        y_positions = list(range(len(windows)))
        for y,(cme,window) in zip(y_positions,windows):
            arrival_ax.barh(y,(window['upper']-window['lower']).total_seconds()/86400.0,
                            left=mdates.date2num(window['lower']),height=.48,
                            color=self.SCALE_COLORS[3],alpha=.28)
            arrival_ax.plot(window['eta'],y,'o',color=self.PALETTE['tertiary'],ms=7)
            arrival_ax.text(window['eta'],y+.27,
                            f"ETA {window['eta']:%Y-%m-%d %H:%M} +/-{window['uncertainty_hours']:.0f} h",
                            fontsize=7,ha='center')
        arrival_ax.set_yticks(y_positions)
        arrival_ax.set_yticklabels([f"CME {i+1}: {c.speed:.0f} km/s" for i,(c,w) in enumerate(windows)])
        arrival_ax.set_title('Screening Earth-arrival windows')
        arrival_ax.xaxis_date(); self._time_axis(arrival_ax)
        return self._save(fig,'cme_arrival_windows','CME arrival windows',
                          'Dedicated launch and arrival timelines. Bands are configurable screening ranges, not validated confidence intervals.')

    def plot_cme_speed_vs_transit(self) -> Optional[str]:
        """Plot speed against modeled transit time; this is not validation."""
        rows = []
        for cme in self.agg.cmes:
            if not cme.is_earth_directed or cme.speed <= 0:
                continue
            window = self.agg.estimate_cme_arrival_window(cme)
            if window and math.isfinite(window['transit_hours']):
                rows.append((float(cme.speed), float(window['transit_hours']), window['method']))
        if not HAS_MATPLOTLIB or not rows:
            self._unavailable('cme_speed_transit', 'CME speed versus modeled transit time',
                              'No Earth-directed CME with a modeled transit time was available.')
            return None
        speed_values = [row[0] for row in rows]
        hour_values = [row[1] for row in rows]
        fig, ax = plt.subplots(figsize=(9.5, 5.5))
        ax.scatter(speed_values, hour_values, s=80, alpha=.76,
                   color=self.PALETTE['primary'], label='Modeled events')
        caption = 'Model-derived screening estimates; not independent validation.'
        if getattr(self, '_has_numpy', lambda: False)() and len(rows) >= 3:
            speeds = np.asarray(speed_values, dtype=float)
            hours = np.asarray(hour_values, dtype=float)
            if np.ptp(speeds) > 0:
                coefficients = np.polyfit(speeds, hours, 1)
                model = np.poly1d(coefficients)
                xline = np.linspace(speeds.min(), speeds.max(), 100)
                predicted = model(speeds)
                total = np.sum((hours-hours.mean())**2)
                residual = np.sum((hours-predicted)**2)
                r2 = 1.0-residual/total if total > 0 else float('nan')
                ax.plot(xline, model(xline), '--', color=self.PALETTE['accent'],
                        lw=1.5, label=f'Linear fit (R2={r2:.2f})')
                caption += (f' Linear-fit R-squared={r2:.2f}; '
                            'the fit summarizes modeled points only.')
        elif not getattr(self, '_has_numpy', lambda: False)():
            caption += ' Linear fitting omitted because NumPy is unavailable.'
        ax.set_xlabel('Plane-of-sky speed [km/s]')
        ax.set_ylabel('Modeled transit time to L1 [hours]')
        ax.set_title('CME speed versus modeled transit time')
        ax.legend(); ax.grid(True, alpha=.3)
        return self._save(fig, 'cme_speed_transit',
                          'CME speed versus modeled transit time', caption)

    def plot_active_regions(self) -> Optional[str]:
        if not HAS_MATPLOTLIB or not self.agg.solar_regions:
            self._unavailable('active_regions', 'NOAA active regions', 'No usable active-region records were available.')
