class SpaceWeatherReportGenerator:
    """Generates formatted space weather reports"""

    def __init__(self, aggregator: SpaceWeatherAggregator,
                 visualizer: Optional['SpaceWeatherVisualizer'] = None):
        self.aggregator = aggregator
        self.risk_engine = RiskAssessmentEngine()
        self.visualizer = visualizer
        self.run_id = str(uuid.uuid4())[:8]

    def _risk_inputs(self) -> Tuple[Dict, Dict]:
        """Collect conditions and derive risk without confusing missing data with quiet data."""
        conditions = self.aggregator.get_current_conditions()
        critical_data_available = any((
            self.aggregator.xray_data,
            self.aggregator.proton_data,
            self.aggregator.solar_wind_data,
            self.aggregator.kp_data,
            self.aggregator.dst_data,
        ))
        if not critical_data_available:
            risk = {
                'overall_risk': 0,
                'level': 'UNKNOWN',
                'xray_risk': 0,
                'proton_risk': 0,
                'geomagnetic_risk': 0,
                'solar_wind_risk': 0,
                'dominant_factor': 'Unavailable',
                'concerns': ['Critical monitoring data is unavailable'],
                'xray_reason': 'No data',
                'proton_reason': 'No data',
                'geo_reason': 'No data',
                'sw_reason': 'No data',
            }
            return conditions, risk
        risk = self.risk_engine.calculate_overall_risk(
            conditions['xray']['current_flux'] or 0.0,
            conditions['xray']['classification'],
            conditions['protons']['flux_10mev'],
            conditions['geomagnetic']['kp'],
            conditions['solar_wind']['speed'],
            conditions['solar_wind']['bz'],
            conditions['solar_wind']['density']
        )
        return conditions, risk

    def generate_quick_check(self) -> str:
        """Generate quick status check"""
        conditions, risk = self._risk_inputs()
        risk_level = risk['overall_risk']
        primary_concern = risk['concerns'][0] if risk['concerns'] else "No significant concerns"

        return f"""
QUICK SPACE WEATHER CHECK
  Run ID:      {self.run_id}
=============================================
  Risk Level: {risk['level']} ({risk_level}/100)
  X-Ray:      {conditions['xray']['classification']}
  Kp Index:   {conditions['geomagnetic']['kp']}
  Solar Wind: {conditions['solar_wind']['speed']:.0f} km/s ({conditions['solar_wind']['source']})
  Active Alerts:  {len(self.aggregator.alerts)}
  Recent Messages:{len(self.aggregator.recent_alert_messages)}
  Outlook:        {self.aggregator.get_forecast_outlook()['level']}
  Active ARs: {len(self.aggregator.solar_regions)}
  F10.7:      {self.aggregator.f107_flux.get('flux', 'N/A')} sfu
  Concern:    {primary_concern}
=============================================
"""

    def generate_full_report(self) -> str:
        """Generate comprehensive space weather report"""
        now = datetime.now(timezone.utc)
        conditions, risk = self._risk_inputs()
        recent_events = self.aggregator.get_recent_events(hours=72)
        threats = self.aggregator.get_threats()

        report_parts = [
            self._generate_header(now),
            self._generate_executive_summary(risk, threats),
            self._generate_current_conditions(conditions),
            self._generate_recent_events(recent_events),
            self._generate_cme_arrival_section(),
            self._generate_historical_analogs(),
            self._generate_solar_activity_context(),
            self._generate_alerts_section(),
            self._generate_data_quality_section(),
            self._generate_forecast_section(risk, conditions),
            self._generate_visuals_section(),
            self._generate_footer(),
        ]

        return '\n'.join(report_parts)

    def _generate_header(self, now: datetime) -> str:
        """Generate report header"""
        return f"""
================================================================================
         SOLAR MISSION CONTROL - COMPREHENSIVE SPACE WEATHER REPORT
================================================================================

  Report Generated: {now.strftime('%Y-%m-%d %H:%M:%S')} UTC
  Run ID:           {self.run_id}
  System Version:   {VERSION}

--------------------------------------------------------------------------------
"""

    def _generate_executive_summary(self, risk: Dict, threats: List[str]) -> str:
        """Generate executive summary section"""
        risk_level = risk['overall_risk']

        descriptions = {
            "EXTREME": "Critical space weather conditions - immediate attention required",
            "SEVERE": "Significant space weather activity - enhanced monitoring required",
            "MODERATE": "Notable space weather activity - maintain awareness",
            "MINOR": "Minor space weather activity - routine monitoring",
            "NOMINAL": "Quiet space weather conditions",
            "UNKNOWN": "Critical monitoring data is unavailable; risk cannot be determined",
        }
        level_desc = descriptions.get(risk['level'], "Unknown conditions")

        def make_bar(value: int, max_val: int = 100) -> str:
            filled = int((value / max_val) * 20)
            return f"[{'#' * filled}{'.' * (20 - filled)}] {value:3d}%"

        qualities = list(self.aggregator.data_quality.values())
        avg_confidence = (sum(q.overall_score for q in qualities) / len(qualities)
                          if qualities else 0.0)

        if risk_level >= 60:
            monitoring = "Continuous (5-min intervals)"
        elif risk_level >= 40:
            monitoring = "Enhanced (15-min intervals)"
        else:
            monitoring = "Standard (hourly)"

        concerns_str = "".join(f"    - {c}\n" for c in risk['concerns'])
        threats_str = "".join(f"    - {t}\n" for t in threats[:15])

        return f"""
                              EXECUTIVE SUMMARY
--------------------------------------------------------------------------------

  CURRENT CONDITIONS: {risk['level']} ({risk_level}/100)
  FORECAST OUTLOOK:  {self.aggregator.get_forecast_outlook()['level']}
  Outlook Reason:    {self.aggregator.get_forecast_outlook()['reason']}
  {level_desc}
  Assessment Confidence: {avg_confidence:.0f}%

  RISK ASSESSMENT BREAKDOWN:

    Solar X-Ray Risk:     {make_bar(risk['xray_risk'])}
    Proton Radiation:     {make_bar(risk['proton_risk'])}
    Geomagnetic Activity: {make_bar(risk['geomagnetic_risk'])}
    Solar Wind Impact:    {make_bar(risk['solar_wind_risk'])}

    Dominant Risk Factor:   {risk['dominant_factor']}
    Recommended Monitoring: {monitoring}

  PRIMARY CONCERNS:
{concerns_str}
  IDENTIFIED THREATS:
{threats_str if threats_str else '    - No immediate threats identified'}
"""

    def _generate_current_conditions(self, conditions: Dict) -> str:
        """Generate current conditions section"""
        xray = conditions['xray']
        protons = conditions['protons']
        solar_wind = conditions['solar_wind']
        geomag = conditions['geomagnetic']

        r_scale_num, r_scale_str = xray['r_scale']

        s_scale_names = {0: "S0 (None)", 1: "S1 (Minor)", 2: "S2 (Moderate)",
                         3: "S3 (Strong)", 4: "S4 (Severe)", 5: "S5 (Extreme)"}
        s_scale_str = s_scale_names.get(protons['s_scale'], "S0 (None)")

        proton_storm_status = "Active" if protons['storm_active'] else "None"

        sw_status = "Normal"
        if solar_wind['speed'] >= 600:
            sw_status = "Elevated"
        elif solar_wind['speed'] >= 500:
            sw_status = "Enhanced"

        if solar_wind['bz'] <= -10:
            bz_indicator = "strongly southward"
        elif solar_wind['bz'] < 0:
            bz_indicator = "southward"
        else:
            bz_indicator = "northward"

        dyn_pressure = 1.67e-6 * solar_wind['density'] * (solar_wind['speed'] ** 2)

        coupling = solar_wind.get('coupling', float('nan'))
        coupling_str = ("N/A" if coupling != coupling
                        else f"{coupling:.0f} ({coupling / 4421.0:.2f} x average)")

        g_scale_names = {0: "G0 (None)", 1: "G1 (Minor)", 2: "G2 (Moderate)",
                         3: "G3 (Strong)", 4: "G4 (Severe)", 5: "G5 (Extreme)"}
        g_scale_str = g_scale_names.get(geomag['g_scale'], "G0 (None)")

        storm_status = "Quiet"
        if geomag['g_scale'] >= 3:
            storm_status = "Major Storm"
        elif geomag['g_scale'] >= 1:
            storm_status = "Storm"

        if geomag['kp'] >= 7:
            aurora = "~45-50 deg latitude (mid-latitudes)"
        elif geomag['kp'] >= 5:
            aurora = "~55-60 deg latitude (high latitudes)"
        elif geomag['kp'] >= 3:
            aurora = "~60-65 deg latitude (subpolar)"
        else:
            aurora = "~65-70 deg latitude (polar regions)"

        ap_estimate = int(geomag['kp'] ** 2.5) if geomag['kp'] > 0 else 0

        flux_str = (f"{xray['current_flux']:.2e} W/m2"
                    if xray['current_flux'] is not None else "N/A")
        peak_str = (f"{xray['peak_24h']:.2e} W/m2"
                    if xray['peak_24h'] is not None else "N/A")
        avg_str = (f"{xray['avg_24h']:.2e} W/m2"
                   if xray['avg_24h'] is not None else "N/A")

        return f"""
                              CURRENT CONDITIONS
--------------------------------------------------------------------------------

    SOLAR X-RAY ACTIVITY
      Current Flux:      {flux_str}
      Classification:    {xray['classification']}
      R-Scale Level:     {r_scale_str}
      24h Peak:          {xray['peak_24h_class']} ({peak_str})
      24h Average:       {avg_str}
      Trend:             {xray['trend']}

    ENERGETIC PROTON ENVIRONMENT
      >10 MeV Flux:      {protons['flux_10mev']:.2f} pfu
      >50 MeV Flux:      {protons['flux_50mev']:.2f} pfu
      >100 MeV Flux:     {protons['flux_100mev']:.3f} pfu
      S-Scale Level:     {s_scale_str}
      Storm Status:      {proton_storm_status}
      72h Peak >10 MeV:  {protons['peak_72h']:.2f} pfu

    INTERPLANETARY MEDIUM (Solar Wind, L1)
      Spacecraft:        {solar_wind['source']}
      Speed:             {solar_wind['speed']:.0f} km/s
      Density:           {solar_wind['density']:.1f} p/cm3
      Temperature:       {solar_wind['temperature']:.2e} K
      IMF Bz:            {solar_wind['bz']:+.1f} nT ({bz_indicator})
      IMF Bt:            {solar_wind['bt']:.1f} nT
      Dynamic Pressure:  {dyn_pressure:.2f} nPa
      Newell Coupling:   {coupling_str}
      Geoeffectiveness:  {solar_wind['geoeffectiveness']}
      Status:            {sw_status}

    GEOMAGNETIC ACTIVITY
      Current Kp:        {geomag['kp']:.1f}
      G-Scale Level:     {g_scale_str}
      Ap Index (est):    {ap_estimate}
      Dst Index:         {geomag['dst']:.0f} nT
      Storm Status:      {storm_status}
      24h Max Kp:        {geomag['max_24h_kp']:.1f}
      24h Min Kp:        {geomag['min_24h_kp']:.1f}
      Aurora Visibility: {aurora}
"""

    def _generate_recent_events(self, events: Dict) -> str:
        """Generate recent events section"""
        flares = events['flares']
        cmes = events['cmes']

        def make_count_bar(count: int, max_count: int = 20) -> str:
            filled = min(count, max_count)
            return f"[{'#' * filled}{'.' * (20 - filled)}] {count:3d}"

        counts = flares['by_class']

        sig_flares_str = ""
        for flare in flares['significant'][:10]:
            duration = f"({flare.duration_minutes} min)" if flare.duration_minutes else ""
            peak_time = (flare.peak_time.strftime('%Y-%m-%d %H:%M')
                         if flare.peak_time else "N/A")
            location = flare.location if flare.location else "N/A"
            ar = flare.active_region if flare.active_region else "N/A"
            sig_flares_str += f"      {flare.class_type} @ {peak_time} UTC {duration}\n"
            sig_flares_str += f"        Location: {location}, AR: {ar}\n"

        if not sig_flares_str:
            sig_flares_str = "      No significant flares in past 72 hours\n"

        cme_stats = cmes['stats']
        now = datetime.now(timezone.utc)

        earth_cmes_str = ""
        for cme in cmes['earth_directed'][:5]:
            time_str = (cme.start_time.strftime('%Y-%m-%d %H:%M')
                        if cme.start_time else "N/A")

            status = "Unknown"
            eta = self.aggregator.estimate_cme_eta(cme)
            if eta:
                hours_until = (eta - now).total_seconds() / 3600
                if hours_until > 48:
                    status = f"Distant ({hours_until:.0f} h)"
                elif hours_until > 0:
                    status = f"Arriving in {hours_until:.1f} h"
                else:
                    status = "Passed / arrived"

            if cme.speed >= 1000:
                impact = "Significant (G3-G5 possible)"
            elif cme.speed >= 700:
                impact = "Moderate (G2-G3 possible)"
            else:
                impact = "Minor (G1-G2 possible)"

            earth_cmes_str += f"      - {time_str} UTC\n"
            earth_cmes_str += f"        Speed: {cme.speed:.0f} km/s, Type: {str(cme.cme_type)[:20]}\n"
            earth_cmes_str += f"        Status: {status}, Impact: {impact}\n"

        if not earth_cmes_str:
            earth_cmes_str = "      No Earth-directed CMEs detected\n"

        return f"""
                           RECENT EVENTS (72 HOURS)
--------------------------------------------------------------------------------

    SOLAR FLARE SUMMARY:

    X-class: {make_count_bar(counts.get('X', 0))}
    M-class: {make_count_bar(counts.get('M', 0))}
    C-class: {make_count_bar(counts.get('C', 0))}
    B-class: {make_count_bar(counts.get('B', 0))}
    A-class: {make_count_bar(counts.get('A', 0))}

    SIGNIFICANT FLARES (M-class and above):
{sig_flares_str}
    Statistics: {flares['total']} total flares, {len(flares['significant'])} significant

    CME STATISTICS:
      Total CMEs:        {cme_stats['total']}
      Earth-Directed:    {cme_stats['earth_directed']}
      Average Speed:     {cme_stats['avg_speed']:.0f} km/s
      Max Speed:         {cme_stats['max_speed']:.0f} km/s
      Min Speed:         {cme_stats['min_speed']:.0f} km/s

    EARTH-DIRECTED CMEs:
{earth_cmes_str}
"""

    def _generate_cme_arrival_section(self) -> str:
        rows=[]
        for cme in self.aggregator.cmes:
            window=self.aggregator.estimate_cme_arrival_window(cme)
            if not window:
                continue
            rows.append(
                f"      Launch {cme.start_time:%Y-%m-%d %H:%M} UTC | {cme.speed:.0f} km/s | "
                f"ETA {window['eta']:%Y-%m-%d %H:%M} UTC | "
                f"window {window['lower']:%m-%d %H:%M} to {window['upper']:%m-%d %H:%M} | "
                f"{window['method']}")
        if not rows:
            return ""
        return """
                         CME ARRIVAL-WINDOW SCREENING
--------------------------------------------------------------------------------
""" + "\n".join(rows[:8]) + """

      Uncertainty bands are configurable screening assumptions, not validated
      confidence intervals. Verify operational decisions with official products.
"""

    def _generate_historical_analogs(self) -> str:
        analogs=self.aggregator.get_historical_analogs()
        if not analogs:
            return ""
        lines=["      HISTORICAL ANALOGS - PATTERN SIMILARITY ONLY:"]
        for item in analogs:
            features=", ".join(item['compared_features'])
            lines.append(
                f"      * {item['name']} ({item['date']}) - {item['similarity']:.1f}% "
                f"pattern match using {features}; source: {item['source']}")
        lines.append("      Pattern similarity is not an impact forecast or event prediction.")
        return """
                         HISTORICAL STORM ANALOGS
--------------------------------------------------------------------------------
""" + "\n".join(lines) + "\n"

    @staticmethod
    def _age_status(observed: Optional[datetime], current_hours: float, stale_hours: float) -> Tuple[str, str]:
        if observed is None:
            return 'UNKNOWN', 'age unavailable'
        age_hours = max(0.0, (datetime.now(timezone.utc) - observed).total_seconds() / 3600.0)
        status = 'CURRENT' if age_hours <= current_hours else 'STALE' if age_hours <= stale_hours else 'OUTDATED'
        return status, f"{age_hours:.1f} h old"

    def _generate_solar_activity_context(self) -> str:
        f107=self.aggregator.f107_flux or {}; flux=f107.get('flux'); tag=f107.get('time_tag','')
        f107_time=parse_swpc_time(tag+'-01') if re.fullmatch(r'\d{4}-\d{2}',str(tag)) else parse_swpc_time(tag)
        f107_status,f107_age=self._age_status(f107_time,24*45,24*120)
        region_date=self.aggregator.solar_regions[0].get('observed_date') if self.aggregator.solar_regions else ''
        region_time=parse_swpc_time(region_date+'T00:00:00') if region_date else None
        region_status,region_age=self._age_status(region_time,48,120)
        activity='Unknown' if flux is None else ('Very high' if flux>=200 else 'High' if flux>=150 else 'Moderate' if flux>=100 else 'Low')
        flux_text='Unavailable' if flux is None else f"{flux:.1f} sfu ({tag})"
        lines=[f"      AR {r['region']:>5} {r['location']:<7} area={r['area']:.0f} mag={r['mag_class']:<5} complexity={r.get('complexity','UNKNOWN'):<22} C/M/X={r['c_probability']:.0f}/{r['m_probability']:.0f}/{r['x_probability']:.0f}%" for r in self.aggregator.solar_regions[:10]]
        regions='\n'.join(lines) if lines else '      Active-region data unavailable'
        max_kp=max((max(0.0,min(9.0,as_float(r.get('kp')))) for r in self.aggregator.kp_forecast[:12]),default=0.0)
        return f"""
                     SOLAR ACTIVITY & AURORAL CONTEXT
--------------------------------------------------------------------------------
    F10.7 CM SOLAR RADIO FLUX:
      Latest monthly value: {flux_text}
      Observation period:   {tag or 'Unavailable'}
      Activity context:     {activity}
      Data status:          Latest available monthly product

    NOAA NUMBERED ACTIVE REGIONS:
      Observation status:   {region_status} ({region_age})
{regions}

    AURORAL SCREENING ESTIMATE:
      Maximum forecast Kp:  {max_kp:.1f}
      Equatorward boundary: ~{self.aggregator.auroral_boundary_latitude(max_kp):.1f} deg geomagnetic latitude
      Note: Kp-derived screening estimate only; use OVATION operationally.

    RISK-TIMELINE CAVEAT:
      History is reconstructed on a three-hour grid using the latest observation
      available before each grid time. The 48-hour extension uses only loaded
      forecast products; unavailable future components are omitted, never zeroed.
      This remains a screening product, not an authoritative continuous forecast.
"""

    def _generate_alerts_section(self) -> str:
        """Generate active alerts section"""
        alerts = self.aggregator.alerts

        if not alerts:
            return """
                                ACTIVE ALERTS
--------------------------------------------------------------------------------

    No active space weather alerts
"""

        extreme_alerts, major_alerts, moderate_alerts, minor_alerts = [], [], [], []

        for alert in alerts:
            message = str(alert.get('message', '')).upper()
            if any(x in message for x in ['EXTREME', 'X10', 'G5', 'S5', 'R5']):
                extreme_alerts.append(alert)
            elif any(x in message for x in ['SEVERE', 'G4', 'S4', 'R4',
                                            'X1', 'X2', 'X3', 'X4', 'X5']):
                major_alerts.append(alert)
            elif any(x in message for x in ['MODERATE', 'G2', 'G3', 'S2',
                                            'S3', 'R2', 'R3', 'M5']):
                moderate_alerts.append(alert)
            else:
                minor_alerts.append(alert)

        def format_alert(alert: Dict) -> str:
            issue_time = alert.get('issue_datetime', 'Unknown')
            message = str(alert.get('message', 'No message'))[:200]

            upper = message.upper()
            if 'FLR' in upper or 'X-RAY' in upper or 'FLARE' in upper:
                alert_type = "Solar Flare"
            elif 'CME' in upper:
                alert_type = "CME"
            elif 'GEOMAG' in upper or 'KP' in upper:
                alert_type = "Geomagnetic"
            elif 'PROTON' in upper:
                alert_type = "Proton Event"
            else:
                alert_type = "General"

            return f"      [{issue_time}] {alert_type}\n        {message}\n"

        output = f"""
                                ACTIVE ALERTS
--------------------------------------------------------------------------------

    ALERT STATISTICS:
      Total Active: {len(alerts)}
      Extreme: {len(extreme_alerts)}   Major: {len(major_alerts)}   Moderate: {len(moderate_alerts)}   Minor: {len(minor_alerts)}
"""

        for label, group in (("EXTREME", extreme_alerts),
                             ("MAJOR", major_alerts),
                             ("MODERATE", moderate_alerts)):
            if group:
                output += f"\n    {label} ({len(group)}):\n"
                output += "    " + "-" * 60 + "\n"
                for alert in group[:3]:
                    output += format_alert(alert) + "\n"

        return output

    def _generate_data_quality_section(self) -> str:
        """Generate data quality section"""
        qualities = self.aggregator.data_quality

        if not qualities:
            return """
                           DATA QUALITY ASSESSMENT
--------------------------------------------------------------------------------

    No data quality metrics available
"""

        avg_confidence = sum(q.overall_score for q in qualities.values()) / len(qualities)

        if avg_confidence >= 80:
            confidence_desc = "HIGH CONFIDENCE - Data is reliable"
        elif avg_confidence >= 60:
            confidence_desc = "MODERATE CONFIDENCE - Some data quality issues"
        else:
            confidence_desc = "LOW CONFIDENCE - Significant data quality issues"

        def make_quality_bar(value: float) -> str:
            filled = int(max(0.0, min(100.0, value)) / 10)
            return f"[{'#' * filled}{'.' * (10 - filled)}] {value:.0f}%"

        output = f"""
                           DATA QUALITY ASSESSMENT
--------------------------------------------------------------------------------

    OVERALL DATA CONFIDENCE: {avg_confidence:.0f}%
    {confidence_desc}
"""

        for quality in qualities.values():
            flags_str = ", ".join(quality.flags) if quality.flags else "None"
            output += f"""
    {quality.source}
      Status:        {quality.status}
      Completeness:  {make_quality_bar(quality.completeness)}
      Freshness:     {make_quality_bar(quality.freshness)}
      Reliability:   {make_quality_bar(quality.reliability)}
      Records:       {quality.record_count}
      Data Gaps:     {quality.data_gaps}
      Flags:         {flags_str}
"""

        return output

    def _generate_visuals_section(self) -> str:
        """Generate the figure and imagery inventory"""
        if self.visualizer is None:
            return """
                            FIGURES AND IMAGERY
--------------------------------------------------------------------------------

    Visual output disabled for this run (--no-plots).
"""

        lines = ""
        plate = 0
        for item in self.visualizer.figures:
            plate += 1
            lines += f"      Plate {plate:>2}  {item['title']}\n"
            lines += f"                {item['path']}\n"
        for item in self.visualizer.images:
            plate += 1
            lines += f"      Plate {plate:>2}  {item['title']}\n"
            lines += f"                {item['path']}\n"

        if not lines:
            lines = "      Nothing was produced. Check matplotlib and network access.\n"

        html_note = os.path.join(self.visualizer.output_dir,
                                 'space_weather_report.html')

        return f"""
                            FIGURES AND IMAGERY
--------------------------------------------------------------------------------

    {len(self.visualizer.figures)} figure(s) and {len(self.visualizer.images)} image(s) produced:

{lines}
    Combined HTML report (figures and images embedded):
      {html_note}
"""

    def _generate_forecast_section(self, risk: Dict, conditions: Dict) -> str:
        """Generate forecast and recommendations section"""

        kp_forecast_str = ""
        if self.aggregator.kp_forecast:
            for forecast in self.aggregator.kp_forecast[:12]:
                time_tag = str(forecast.get('time_tag', 'Unknown'))
                kp = forecast.get('kp', 0.0)
                g_scale = self.aggregator._kp_to_g_scale(kp)
                bar_filled = min(int(kp), 9)
                bar = "#" * bar_filled + "." * (9 - bar_filled)
                kp_forecast_str += f"      {time_tag[:16]} [{bar}] Kp={kp:.0f}  G{g_scale}\n"
        else:
            kp_forecast_str = "      Forecast data unavailable\n"

        probs = self.aggregator.flare_probabilities or {}
        c_prob = as_float(get_key(probs, 'c_class_1_day', 'C', 'c_class'))
        m_prob = as_float(get_key(probs, 'm_class_1_day', 'M', 'm_class'))
        x_prob = as_float(get_key(probs, 'x_class_1_day', 'X', 'x_class'))
        proton_prob = as_float(get_key(probs, '10mev_protons_1_day',
                                       'proton', 's1_or_greater'))

        def make_prob_bar(prob: float) -> str:
            filled = int(max(0.0, min(100.0, prob)) / 5)
            return "#" * filled

        recommendations = []
        if risk['overall_risk'] >= 80:
            recommendations.extend([
                "CRITICAL: Consider postponing EVA activities",
                "CRITICAL: Implement radiation protection protocols",
                "CRITICAL: Increase monitoring to 5-minute intervals",
                "CRITICAL: Brief all stakeholders immediately",
                "CRITICAL: Prepare contingency communication plans"
            ])
        elif risk['overall_risk'] >= 60:
            recommendations.extend([
                "URGENT: Evaluate EVA risk assessment",
                "URGENT: Monitor radiation levels closely",
                "URGENT: Prepare for potential HF radio disruptions"
            ])
        elif risk['overall_risk'] >= 40:
            recommendations.extend([
                "CAUTION: Enhanced monitoring recommended",
                "CAUTION: Be prepared for minor disruptions"
            ])
        else:
            recommendations.append("NOMINAL: Continue standard operations")

        if risk['xray_risk'] >= 40:
            recommendations.append("FLARE: Monitor for radio communication impacts")
        if risk['proton_risk'] >= 40:
            recommendations.append("PROTON: Evaluate polar flight routes")
        if risk['geomagnetic_risk'] >= 40:
            recommendations.append("GEOMAG: GPS accuracy may be affected")
        if risk['solar_wind_risk'] >= 40:
            recommendations.append("SOLAR WIND: Watch for increasing geomagnetic activity")

        recommendations_str = "\n".join(f"      {r}" for r in recommendations)

        impacts = {
            'HF Radio Communications': 'MINIMAL',
            'Satellite Operations': 'MINIMAL',
            'GPS/Navigation': 'MINIMAL',
            'Power Grid Systems': 'MINIMAL',
            'Aviation (Polar Routes)': 'MINIMAL',
            'Spacecraft Electronics': 'MINIMAL',
            'Astronaut Radiation': 'MINIMAL',
            'Pipeline Operations': 'MINIMAL',
            'Aurora Visibility': 'NORMAL'
        }

        if risk['xray_risk'] >= 60:
            impacts['HF Radio Communications'] = 'SEVERE'
            impacts['Satellite Operations'] = 'MODERATE'
        elif risk['xray_risk'] >= 40:
            impacts['HF Radio Communications'] = 'MODERATE'
            impacts['Satellite Operations'] = 'MODERATE'

        if risk['proton_risk'] >= 60:
            impacts['Aviation (Polar Routes)'] = 'SEVERE'
            impacts['Astronaut Radiation'] = 'SEVERE'
            impacts['Spacecraft Electronics'] = 'MODERATE'
        elif risk['proton_risk'] >= 40:
            impacts['Aviation (Polar Routes)'] = 'MODERATE'
            impacts['Astronaut Radiation'] = 'MODERATE'

        if risk['geomagnetic_risk'] >= 60:
            impacts['GPS/Navigation'] = 'SEVERE'
            impacts['Power Grid Systems'] = 'MODERATE'
            impacts['Pipeline Operations'] = 'MODERATE'
            impacts['Aurora Visibility'] = 'ENHANCED'
        elif risk['geomagnetic_risk'] >= 40:
            impacts['GPS/Navigation'] = 'MODERATE'
            impacts['Aurora Visibility'] = 'ENHANCED'

        def impact_label(level: str) -> str:
            return {'SEVERE': 'SEVERE  ', 'MODERATE': 'MODERATE',
                    'MINIMAL': 'MINIMAL ', 'NORMAL': 'NORMAL  ',
                    'ENHANCED': 'ENHANCED'}.get(level, str(level))

        impacts_str = "\n".join(f"      {impact_label(level)} | {system}"
                                for system, level in impacts.items())

        return f"""
                          FORECAST & RECOMMENDATIONS
--------------------------------------------------------------------------------

    Kp INDEX FORECAST (next 36 hours):
{kp_forecast_str}
    24-HOUR FLARE PROBABILITIES:
      C-class:      {c_prob:.0f}% {make_prob_bar(c_prob)}
      M-class:      {m_prob:.0f}% {make_prob_bar(m_prob)}
      X-class:      {x_prob:.0f}% {make_prob_bar(x_prob)}
      Proton Event: {proton_prob:.0f}% {make_prob_bar(proton_prob)}

    OPERATIONAL RECOMMENDATIONS:
{recommendations_str}

    SYSTEM IMPACT ASSESSMENT:
{impacts_str}

"""

    def _generate_footer(self) -> str:
        """Generate report footer"""
        return f"""
--------------------------------------------------------------------------------

  DATA SOURCES:
     - NOAA Space Weather Prediction Center (SWPC)
     - NOAA F10.7 solar-cycle and numbered-region JSON products
     - NASA DONKI (Space Weather Database)
     - GOES Satellite (X-ray and particle data)
     - RTSW L1 fleet (SOLAR-1 / IMAP / DSCOVR / ACE, active source flagged)
     - SDO (AIA, HMI) and SOHO/LASCO imagery

  DISCLAIMER:
     This report is automatically generated from publicly available data.
     Always verify critical decisions with official NOAA/NASA advisories.
     Data may be delayed or incomplete during high activity periods.

  OFFICIAL RESOURCES:
     - https://www.swpc.noaa.gov
     - https://kauai.ccmc.gsfc.nasa.gov/DONKI

================================================================================
Solar Mission Control v{VERSION}                                  - End of Report
================================================================================
"""


