def dependency_health() -> Dict[str, Any]:
    """Return dependency and runtime status without network access."""
    import importlib.util
    modules = ('numpy', 'matplotlib', 'PIL', 'astropy', 'sunpy',
               'plotly', 'reportlab', 'requests', 'sqlite3')
    status = {}
    for name in modules:
        try:
            status[name] = importlib.util.find_spec(name) is not None
        except Exception:
            status[name] = False
    return {
        'version': VERSION, 'python': sys.version.split()[0],
        'dependencies': status,
        'output_2k': [DEFAULT_OUTPUT_WIDTH, DEFAULT_OUTPUT_HEIGHT],
        'nasa_key_configured': NASA_API_KEY not in ('', 'DEMO_KEY'),
        'timestamp': datetime.now(timezone.utc).isoformat(),
    }

def initialize_run_database(output_dir: str) -> Tuple[sqlite3.Connection, str]:
    os.makedirs(output_dir, exist_ok=True)
    database_path = os.path.join(output_dir, 'solar_mission_control.db')
    connection = sqlite3.connect(database_path)
    existing = connection.execute(
        "SELECT name FROM sqlite_master WHERE type='table' AND name='runs'"
    ).fetchone()
    required = {'run_id', 'started_at', 'ended_at', 'version',
                'status', 'output_dir', 'warning'}
    if existing:
        columns = {row[1] for row in connection.execute('PRAGMA table_info(runs)')}
        if not required.issubset(columns):
            suffix = datetime.now(timezone.utc).strftime('%Y%m%d_%H%M%S')
            legacy_name = f'runs_legacy_{suffix}'
            connection.execute(f'ALTER TABLE runs RENAME TO "{legacy_name}"')
            print(f'  Legacy run table renamed to {legacy_name}')
    connection.execute("CREATE TABLE IF NOT EXISTS runs ("
                       "run_id TEXT PRIMARY KEY, started_at TEXT NOT NULL, "
                       "ended_at TEXT, version TEXT NOT NULL, status TEXT NOT NULL, "
                       "output_dir TEXT NOT NULL, warning TEXT)")
    run_id = str(uuid.uuid4())
    connection.execute(
        'INSERT INTO runs(run_id, started_at, version, status, output_dir) VALUES (?,?,?,?,?)',
        (run_id, datetime.now(timezone.utc).isoformat(), VERSION, 'running', output_dir))
    connection.commit()
    return connection, run_id

def cleanup_old_runs(connection: sqlite3.Connection, retention_days: int = 180) -> int:
    retention_days = max(1, int(retention_days))
    cutoff = (datetime.now(timezone.utc)-timedelta(days=retention_days)).isoformat()
    cursor = connection.execute(
        "DELETE FROM runs WHERE started_at < ? AND status != 'extreme_event'",
        (cutoff,))
    connection.commit()
    return cursor.rowcount


def close_run_database(connection: sqlite3.Connection, run_id: str,
                       status: str, warning: str = '') -> None:
    connection.execute(
        'UPDATE runs SET ended_at=?, status=?, warning=? WHERE run_id=?',
        (datetime.now(timezone.utc).isoformat(), status, warning, run_id))
    connection.commit()
    connection.close()


def write_pdf_report(text_report: str, visualizer: Optional[SpaceWeatherVisualizer],
                     output_dir: str) -> Optional[str]:
    try:
        from reportlab.lib.pagesizes import A4
        from reportlab.lib.styles import getSampleStyleSheet
        from reportlab.lib.units import cm
        from reportlab.platypus import (SimpleDocTemplate, Paragraph, Spacer,
                                        Image as PDFImage, PageBreak, Preformatted)
    except ImportError:
        print('  PDF export skipped: ReportLab is not installed.')
        return None
    path = os.path.join(output_dir, 'solar_mission_control_report.pdf')
    styles = getSampleStyleSheet()
    document = SimpleDocTemplate(path, pagesize=A4, leftMargin=1.25*cm,
                                 rightMargin=1.25*cm, topMargin=1.2*cm,
                                 bottomMargin=1.2*cm)
    story = [Paragraph('Solar Mission Control', styles['Title']),
             Paragraph(f'Version {VERSION}', styles['Normal']), Spacer(1, 12),
             Preformatted(text_report, styles['Code'], maxLineLength=105)]
    if visualizer:
        for item in visualizer.figures + visualizer.images:
            image_path = item.get('path')
            if not image_path or not os.path.exists(image_path):
                continue
            try:
                story.extend([PageBreak(),
                              Paragraph(item.get('title', 'Plate'), styles['Heading2']),
                              Spacer(1, 8),
                              PDFImage(image_path, width=17*cm, height=9.6*cm,
                                       kind='proportional'),
                              Spacer(1, 6),
                              Paragraph(item.get('caption', ''), styles['BodyText'])])
            except Exception as exc:
                story.append(Paragraph(
                    f'[Image could not be embedded: {type(exc).__name__}]',
                    styles['Normal']))
    document.build(story)
    print(f'  PDF report written: {path}')
    return path

def write_interactive_timeline(aggregator: SpaceWeatherAggregator,
                               output_dir: str, hours_back: int = 72,
                               hours_forward: int = 48) -> Optional[str]:
    try:
        import plotly.graph_objects as go
    except ImportError:
        print('  Interactive timeline skipped: Plotly is not installed.')
        return None
    if not HAS_NUMPY:
        print('  Interactive timeline skipped: NumPy is required.')
        return None
    rows = aggregator.build_risk_timeline(hours_back, hours_forward, 3)
    if not rows:
        print('  Interactive timeline skipped: no usable risk timeline data.')
        return None
    figure = go.Figure()
    for key in ('composite', 'xray', 'proton', 'geomagnetic', 'solar_wind'):
        valid = [row for row in rows if row.get(key) is not None]
        figure.add_trace(go.Scatter(
            x=[row['timestamp'] for row in valid], y=[row[key] for row in valid],
            mode='lines+markers', name=key.replace('_', ' ').title()))
    figure.update_layout(title='Interactive Risk Timeline',
                         yaxis_title='Risk [0-100]', yaxis_range=[0, 100],
                         xaxis_title='UTC', template='plotly_white',
                         hovermode='x unified')
    path = os.path.join(output_dir, 'interactive_risk_timeline.html')
    figure.write_html(path, include_plotlyjs=True)
    print(f'  Interactive timeline written: {path}')
    return path

def alert_payload(app: 'SolarMissionControl', run_id: str) -> Dict[str, Any]:
    conditions, risk = app.report_generator._risk_inputs()
    outlook = app.aggregator.get_forecast_outlook()
    return {
        'version': VERSION, 'run_id': run_id,
        'generated_at': datetime.now(timezone.utc).isoformat(),
        'current_level': risk['level'], 'current_score': risk['overall_risk'],
        'forecast_level': outlook['level'], 'peak_forecast_kp': outlook['peak_kp'],
        'active_alerts': len(app.aggregator.alerts),
        'earth_directed_cmes': sum(c.is_earth_directed for c in app.aggregator.cmes),
        'solar_wind_source': conditions['solar_wind']['source'],
    }


def is_duplicate_alert(payload: Dict[str, Any], cooldown_minutes: int = 60) -> bool:
    """Placeholder until persistent delivery fingerprint storage is implemented."""
    _ = hashlib.sha256(json.dumps(payload, sort_keys=True).encode()).hexdigest()
    _ = max(1, int(cooldown_minutes))
    return False


def send_webhook_alert(payload: Dict[str, Any], dry_run: bool = False) -> Dict[str, Any]:
    fingerprint = hashlib.sha256(json.dumps(payload, sort_keys=True).encode()).hexdigest()
    if dry_run:
        return {'dry_run': True, 'fingerprint': fingerprint, 'payload': payload}
    url = os.getenv('SPACE_WEATHER_WEBHOOK', '').strip()
    if not url:
        return {'skipped': 'SPACE_WEATHER_WEBHOOK is not configured',
                'fingerprint': fingerprint}
    try:
        response = requests.post(url, json=payload, timeout=10)
        response.raise_for_status()
        return {'sent': True, 'status_code': response.status_code,
                'fingerprint': fingerprint}
    except requests.exceptions.RequestException as exc:
        return {'error': f'Webhook delivery failed: {type(exc).__name__}',
                'fingerprint': fingerprint}

def run_scheduled(interval_minutes: int, output_dir: str, run_once=None) -> None:
    """Run a supplied callable repeatedly while holding a nonblocking lock.

    This helper is intended for Linux/Colab/Docker. The CLI --loop option remains
    the normal entry point. A callable is required to avoid recursively invoking
    main() with notebook-owned command-line arguments.
    """
    if run_once is None or not callable(run_once):
        raise ValueError('run_scheduled requires a callable run_once argument')
    os.makedirs(output_dir, exist_ok=True)
    lock_path = os.path.join(output_dir, '.monitor.lock')
    lock_file = open(lock_path, 'w', encoding='utf-8')
    try:
        try:
            import fcntl
            fcntl.flock(lock_file, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except ImportError:
            print('  Scheduler lock warning: fcntl is unavailable on this platform.')
        except BlockingIOError:
            print('Another monitoring instance is already running. Exiting.')
            return
        while True:
            run_once()
            time.sleep(max(1, int(interval_minutes)) * 60)
    finally:
        lock_file.close()


# ============================================================================
# MAIN APPLICATION
# ============================================================================

class SolarMissionControl:
    """Main application class"""

    def __init__(self, nasa_api_key: str = NASA_API_KEY,
                 output_dir: str = "swrl_report",
                 with_plots: bool = True,
                 with_images: bool = True,
                 write_html: bool = True):
        self.aggregator = SpaceWeatherAggregator(nasa_api_key)
        self.output_dir = output_dir
        self.with_plots = with_plots and HAS_MATPLOTLIB
        self.with_images = with_images
        self.write_html = write_html
        self.visualizer: Optional[SpaceWeatherVisualizer] = None
        self.report_generator = SpaceWeatherReportGenerator(self.aggregator)

    def run(self, quick_check: bool = False, hours_back: int = 48,
            hours_forward: int = 48):
        """Run the space weather monitoring system"""
        print("\n" + "=" * 80)
        print("         SOLAR MISSION CONTROL - Space Weather Monitoring System")
        print("=" * 80 + "\n")

        self.aggregator.fetch_all_data(hours_back=hours_back,
                                       hours_forward=hours_forward)

        print("\n" + "-" * 80 + "\n")
        print(self.report_generator.generate_quick_check())

        if self.with_plots and not quick_check:
            conditions, risk = self.report_generator._risk_inputs()
            events = self.aggregator.get_recent_events(hours=72)

            self.visualizer = SpaceWeatherVisualizer(
                self.aggregator,
                output_dir=self.output_dir,
                include_images=self.with_images
            )
            self.report_generator.visualizer = self.visualizer
            self.visualizer.build_all(risk, events)

        if not quick_check:
            report_text = self.report_generator.generate_full_report()
            print(report_text)

            try:
                os.makedirs(self.output_dir, exist_ok=True)
                text_path = os.path.join(self.output_dir,
                                         'space_weather_report.txt')
                with open(text_path, 'w', encoding='utf-8') as handle:
                    handle.write(report_text)
                print(f"  Text report written: {text_path}")
            except OSError as e:
                print(f"  Could not write text report: {e}")

            if self.visualizer and self.write_html:
                conditions, risk = self.report_generator._risk_inputs()
                self.visualizer.build_html_report(report_text, conditions, risk)

            if self.visualizer:
                self.visualizer.display_inline()

        conditions = self.aggregator.get_current_conditions()
        return conditions['xray']['classification']


# ============================================================================
# ENTRY POINT
# ============================================================================

def main():
    """Standalone v3 entry point for terminal, Colab, and Docker."""
    import argparse
    parser = argparse.ArgumentParser(
        description=f'Solar Mission Control v{VERSION} - standalone',
        formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument('command', nargs='?', default='run',
                        choices=['run', 'quick', 'health', 'alert'])
    parser.add_argument('--quick', '-q', action='store_true',
                        help='Alias for the quick command')
    parser.add_argument('--hours-back', '-b', type=int, default=48)
    parser.add_argument('--hours-forward', '-F', type=int, default=48)
    parser.add_argument('--api-key', '-k', default=NASA_API_KEY)
    parser.add_argument('--loop', '-l', type=int, default=0)
    parser.add_argument('--output-dir', '-o', default='swrl_report')
    parser.add_argument('--no-plots', action='store_true')
    parser.add_argument('--no-images', action='store_true')
    parser.add_argument('--no-html', action='store_true')
    parser.add_argument('--pdf', action='store_true',
                        help='Write a multi-page PDF if ReportLab is installed')
    parser.add_argument('--interactive', action='store_true',
                        help='Write an interactive Plotly risk timeline')
    parser.add_argument('--no-interactive', action='store_true',
                        help='Force disable interactive Plotly output')
    parser.add_argument('--retention-days', type=int, default=180,
                        help='Days to keep run history in SQLite')
    parser.add_argument('--dry-run', action='store_true',
                        help='Build but do not send an alert webhook')
    # Colab/Jupyter starts the kernel with arguments such as:
    #   -f /root/.local/share/jupyter/runtime/kernel-....json
    # Because this program has an optional positional command, parse_known_args()
    # alone is insufficient: argparse can consume the kernel JSON path as that
    # positional command before it has a chance to classify it as unknown.
    # Remove kernel-owned arguments first while preserving arguments supplied
    # through %run, subprocess, terminal execution, or Docker.
    raw_argv = list(sys.argv[1:])
    clean_argv = []
    index = 0
    while index < len(raw_argv):
        token = raw_argv[index]
        if token in ('-f', '--f', '--file'):
            index += 2  # discard the flag and its kernel connection file
            continue
        if token.startswith('--HistoryManager.') or token.startswith('--IPKernelApp.'):
            index += 1
            continue
        if token.endswith('.json') and ('/jupyter/runtime/' in token or '/runtime/kernel-' in token):
            index += 1
            continue
        clean_argv.append(token)
        index += 1
    args, unknown = parser.parse_known_args(clean_argv)
    if unknown and 'ipykernel' not in sys.modules and 'google.colab' not in sys.modules:
        print('Warning: unrecognized arguments ignored:', ' '.join(unknown))
    if args.command == 'health':
        print(json.dumps(dependency_health(), indent=2))
        return
    quick = args.quick or args.command == 'quick'
    connection, run_id = initialize_run_database(args.output_dir)
    status, warning = 'complete', ''
    try:
        app = SolarMissionControl(
            nasa_api_key=args.api_key, output_dir=args.output_dir,
            with_plots=not args.no_plots, with_images=not args.no_images,
            write_html=not args.no_html)
        def execute_once():
            app.report_generator.run_id = run_id[:8]
            classification = app.run(
                quick_check=quick, hours_back=args.hours_back,
                hours_forward=args.hours_forward)
            if not quick:
                report = app.report_generator.generate_full_report()
                if args.pdf:
                    write_pdf_report(report, app.visualizer, args.output_dir)
                if not args.no_interactive:
                    write_interactive_timeline(app.aggregator, args.output_dir,
                                               args.hours_back, args.hours_forward)
            if args.command == 'alert':
                result = send_webhook_alert(alert_payload(app, run_id), args.dry_run)
                print(json.dumps(result, indent=2))
            return classification
        if args.loop > 0:
            print(f'Starting continuous monitoring every {args.loop} minutes')
            while True:
                print(f'\n{execute_once()}\n')
                time.sleep(args.loop * 60)
        else:
            print(f'\n{execute_once()}\n')
    except KeyboardInterrupt:
        status = 'stopped'
        print('\nMonitoring stopped by user')
    except Exception as exc:
        status = 'failed'
        warning = f'{type(exc).__name__}: {exc}'
        raise
    finally:
        close_run_database(connection, run_id, status, warning)
        if status == 'complete':
            try:
                cleanup_connection = sqlite3.connect(
                    os.path.join(args.output_dir, 'solar_mission_control.db'))
                deleted = cleanup_old_runs(cleanup_connection, args.retention_days)
                cleanup_connection.close()
                print(f'  Cleaned up {deleted} old run records.')
            except Exception as exc:
                print(f'  Run-history cleanup skipped: {type(exc).__name__}')


if __name__ == '__main__':
    main()
